-- ===================================================================
-- PATCH — cria o módulo "Quiz Turismo" (500 perguntas sobre
-- monumentos e maravilhas do mundo, separado do banco geral).
--
-- COMO USAR: cole este arquivo inteiro no SQL Editor do Supabase e
-- clique em "Run". Ele cria uma tabela NOVA (tourism_questions) e
-- adiciona uma coluna nova (module) na tabela results — NÃO apaga nem
-- altera nenhuma pergunta ou resultado já existente do quiz geral.
-- ===================================================================

-- ===================== TABELA: tourism_questions =====================
-- Banco de perguntas do módulo de turismo. Mesma estrutura da tabela
-- "questions" (quiz geral), mas totalmente separada.
create table if not exists tourism_questions (
  id bigint generated always as identity primary key,
  question text not null,
  options jsonb not null,
  correct_index smallint not null check (correct_index between 0 and 3),
  explanation text not null,
  created_at timestamptz not null default now()
);

alter table tourism_questions enable row level security;

drop policy if exists "tourism_questions_select_public" on tourism_questions;
create policy "tourism_questions_select_public"
  on tourism_questions for select
  to anon
  using (true);

-- ===================== COLUNA: results.module =====================
-- Identifica qual módulo foi jogado em cada resultado ('geral' ou
-- 'turismo'). Resultados antigos (antes deste patch) ficam com o
-- valor padrão 'geral'.
alter table results add column if not exists module text not null default 'geral';

-- ===================== SEED: 500 perguntas de turismo =====================
-- (Se rodar este script mais de uma vez, isso vai duplicar as perguntas
--  de turismo. Para evitar duplicidade, rode "delete from tourism_questions;"
--  antes de repetir apenas essa parte.)


-- ===================== FIM DO PATCH =====================
-- Se tudo rodou sem erro, o módulo "Quiz Turismo" já está disponível!
