insert into tourism_questions (question, options, correct_index, explanation) values ('Quantas das Sete Maravilhas do Mundo Antigo ainda existem de pé atualmente?', '["Nenhuma","Apenas uma","Duas","Três"]'::jsonb, 1, 'Apenas a Grande Pirâmide de Gizé, no Egito, ainda existe. As outras seis foram destruídas ao longo dos séculos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual das Sete Maravilhas do Mundo Antigo é a única que ainda existe hoje?', '["O Farol de Alexandria","A Grande Pirâmide de Gizé","O Colosso de Rodes","Os Jardins Suspensos da Babilônia"]'::jsonb, 1, 'A Grande Pirâmide de Gizé, construída como tumba do faraó Quéops, é a mais antiga das sete e a única que resistiu até os dias atuais.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Em qual país está localizada a Grande Pirâmide de Gizé?', '["Egito","Sudão","Iraque","Grécia"]'::jsonb, 0, 'A Grande Pirâmide de Gizé fica no Egito, próxima à cidade do Cairo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Para qual faraó egípcio a Grande Pirâmide de Gizé foi construída como tumba?', '["Tutancâmon","Ramsés II","Quéops (Khufu)","Amenófis III"]'::jsonb, 2, 'A Grande Pirâmide foi construída como túmulo para o faraó Quéops (também chamado Khufu), da Quarta Dinastia do Egito.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Onde ficavam, segundo a tradição, os Jardins Suspensos da Babilônia?', '["No Egito","Na atual região do Iraque","Na Grécia","Na Turquia"]'::jsonb, 1, 'Os Jardins Suspensos teriam ficado na antiga cidade da Babilônia, na região onde hoje fica o Iraque.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual das Sete Maravilhas do Mundo Antigo tem sua própria existência histórica questionada por arqueólogos?', '["A Grande Pirâmide de Gizé","O Farol de Alexandria","Os Jardins Suspensos da Babilônia","O Colosso de Rodes"]'::jsonb, 2, 'Não foram encontrados registros arqueológicos definitivos dos Jardins Suspensos da Babilônia, e há debate acadêmico sobre se eles realmente existiram.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Estátua de Zeus, uma das Sete Maravilhas do Mundo Antigo, ficava em qual cidade grega?', '["Atenas","Esparta","Olímpia","Delfos"]'::jsonb, 2, 'A Estátua de Zeus ficava no templo dedicado ao deus em Olímpia, sede dos Jogos Olímpicos da Antiguidade.');
insert into tourism_questions (question, options, correct_index, explanation) values ('De que material era feita, principalmente, a Estátua de Zeus em Olímpia?', '["Bronze maciço","Mármore branco","Ouro e marfim sobre estrutura de madeira","Granito"]'::jsonb, 2, 'A estátua era do tipo criselefantina, feita com placas de ouro e marfim montadas sobre uma estrutura de madeira.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo de Ártemis, uma das Sete Maravilhas do Mundo Antigo, ficava em qual cidade?', '["Éfeso","Rodes","Alexandria","Halicarnasso"]'::jsonb, 0, 'O Templo de Ártemis ficava na cidade de Éfeso, na costa da atual Turquia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A qual deusa grega era dedicado o templo de Éfeso, uma das Sete Maravilhas do Mundo Antigo?', '["Atena","Afrodite","Ártemis","Hera"]'::jsonb, 2, 'O templo era dedicado a Ártemis, deusa da caça e da natureza selvagem na mitologia grega.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Mausoléu de Halicarnasso foi construído como túmulo para qual figura histórica?', '["Alexandre, o Grande","O sátrapa Mausolo","O faraó Quéops","O imperador Nero"]'::jsonb, 1, 'O Mausoléu foi construído como túmulo monumental para Mausolo, governante (sátrapa) da região da Cária, e sua esposa Artemísia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('De onde vem a palavra ''mausoléu'', usada até hoje para designar túmulos monumentais?', '["Do nome do arquiteto que o projetou","Do nome do governante Mausolo, para quem foi construído","Do local onde ficava, a cidade de Halicarnasso","De uma palavra grega que significa ''pedra''"]'::jsonb, 1, 'O termo ''mausoléu'' deriva diretamente do nome de Mausolo, governante para quem o monumento original foi erguido.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Colosso de Rodes era uma estátua gigante representando qual figura?', '["Zeus, rei dos deuses","Hélios, o deus do sol","Poseidon, deus dos mares","Atena, deusa da sabedoria"]'::jsonb, 1, 'O Colosso de Rodes era uma estátua de bronze representando Hélios, o deus grego do sol, erguida na ilha de Rodes.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que se acredita ter causado a queda do Colosso de Rodes, uma das Sete Maravilhas do Mundo Antigo?', '["Um incêndio","Um terremoto","Uma invasão militar","O desgaste natural do tempo"]'::jsonb, 1, 'De acordo com relatos históricos, um terremoto por volta de 226 a.C. derrubou a estátua, que ficou caída por séculos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Farol de Alexandria, uma das Sete Maravilhas do Mundo Antigo, ficava em qual país?', '["Grécia","Turquia","Egito","Líbano"]'::jsonb, 2, 'O Farol de Alexandria ficava na ilha de Faro, na costa da cidade egípcia de Alexandria.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual era a principal função do Farol de Alexandria?', '["Servir de templo religioso","Guiar embarcações até o porto da cidade","Ser um túmulo real","Observar os astros"]'::jsonb, 1, 'O farol foi construído para guiar navios com segurança até o movimentado porto de Alexandria, no Egito.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Para qual rei egípcio o Farol de Alexandria foi construído?', '["Ptolomeu II","Ramsés II","Tutancâmon","Alexandre, o Grande"]'::jsonb, 0, 'O farol foi construído durante o reinado de Ptolomeu II, no século III a.C.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Quem foi o autor da primeira lista conhecida das ''Sete Maravilhas do Mundo'', escrita por volta de 225 a.C.?', '["Heródoto","Filo de Bizâncio","Aristóteles","Platão"]'::jsonb, 1, 'Filo de Bizâncio escreveu a obra ''Sobre as Sete Maravilhas'', uma das primeiras compilações conhecidas da lista.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Por quantos anos, aproximadamente, as sete maravilhas do mundo antigo existiram todas ao mesmo tempo?', '["Menos de 60 anos","Cerca de 500 anos","Mais de 1000 anos","Elas nunca coexistiram"]'::jsonb, 0, 'Segundo historiadores, as sete estruturas estiveram de pé simultaneamente por menos de 60 anos, já que foram construídas e destruídas em épocas diferentes.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual das Sete Maravilhas do Mundo Antigo está localizada mais ao norte, na região da atual Turquia?', '["O Templo de Ártemis, em Éfeso","A Grande Pirâmide de Gizé","O Farol de Alexandria","O Colosso de Rodes"]'::jsonb, 0, 'O Templo de Ártemis ficava em Éfeso, na costa oeste da atual Turquia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Mausoléu de Halicarnasso ficava em uma região que hoje pertence a qual país?', '["Grécia","Turquia","Chipre","Síria"]'::jsonb, 1, 'Halicarnasso corresponde à atual cidade de Bodrum, na Turquia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Estátua de Zeus em Olímpia foi criada por qual famoso escultor grego?', '["Fídias","Praxíteles","Miron","Policleto"]'::jsonb, 0, 'A estátua foi obra do escultor Fídias, também responsável por trabalhos no Partenon de Atenas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Aproximadamente quantos metros de altura tinha a Grande Pirâmide de Gizé em sua construção original?', '["Cerca de 100 metros","Cerca de 147 metros","Cerca de 200 metros","Cerca de 60 metros"]'::jsonb, 1, 'Estima-se que a pirâmide tinha originalmente cerca de 146-147 metros de altura, antes da perda de seu revestimento externo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Colosso de Rodes ficava na entrada de qual porto?', '["O porto da ilha de Rodes","O porto de Atenas","O porto de Alexandria","O porto de Éfeso"]'::jsonb, 0, 'A estátua ficava próxima ao porto da cidade de Rodes, na ilha grega de mesmo nome.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Segundo a tradição, quem teria mandado construir os Jardins Suspensos da Babilônia?', '["O rei Nabucodonosor II","O faraó Ramsés II","Alexandre, o Grande","O imperador Dario I"]'::jsonb, 0, 'A tradição atribui a construção dos Jardins Suspensos ao rei babilônico Nabucodonosor II, que teria os erguido para agradar sua esposa.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo de Ártemis em Éfeso foi reconstruído várias vezes ao longo da história. O que causou uma de suas destruições?', '["Um incêndio criminoso","Uma erupção vulcânica","Um tsunami","Uma epidemia"]'::jsonb, 0, 'Uma das versões do templo foi incendiada propositalmente por Herostrato, que buscava fama através do ato, no século IV a.C.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Quantos metros de altura, aproximadamente, tinha o Colosso de Rodes?', '["Cerca de 10 metros","Cerca de 33 metros","Cerca de 70 metros","Cerca de 150 metros"]'::jsonb, 1, 'Estima-se que o Colosso de Rodes tivesse cerca de 33 metros de altura, aproximadamente o tamanho da Estátua da Liberdade sem o pedestal.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual material predominava na construção da Grande Pirâmide de Gizé?', '["Tijolos de barro","Blocos de calcário e granito","Mármore branco","Madeira de cedro"]'::jsonb, 1, 'A pirâmide foi construída principalmente com blocos de calcário, com granito usado em partes internas como a câmara funerária.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Farol de Alexandria é considerado o precursor de qual tipo de construção moderna?', '["Os arranha-céus","Os faróis marítimos","As pontes suspensas","Os aeroportos"]'::jsonb, 1, 'O Farol de Alexandria é referência histórica para os faróis marítimos construídos até hoje ao redor do mundo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que provocou a destruição final do Farol de Alexandria, muitos séculos após sua construção?', '["Uma série de terremotos","Um ataque naval","Um incêndio florestal","A erosão do mar"]'::jsonb, 0, 'Uma sequência de terremotos entre os séculos XI e XIV danificou progressivamente o farol até sua queda definitiva.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Na mitologia grega, Hélios — representado pelo Colosso de Rodes — era o deus responsável por quê?', '["Guiar o carro do sol pelo céu","Governar os mares","Proteger os guerreiros na batalha","Cuidar das colheitas"]'::jsonb, 0, 'Hélios era o deus grego que, segundo o mito, conduzia o carro solar através do céu todos os dias.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual das Sete Maravilhas do Mundo Antigo ficava mais próxima do Mar Mediterrâneo, servindo de referência para navegantes?', '["O Farol de Alexandria","A Estátua de Zeus em Olímpia","O Mausoléu de Halicarnasso","Os Jardins Suspensos da Babilônia"]'::jsonb, 0, 'O Farol de Alexandria, erguido na costa egípcia, foi construído justamente para orientar embarcações que navegavam pelo Mediterrâneo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Grande Pirâmide de Gizé faz parte de um complexo que inclui qual outro monumento famoso?', '["A Esfinge de Gizé","O Templo de Karnak","O Vale dos Reis","A Coluna de Trajano"]'::jsonb, 0, 'A Grande Pirâmide faz parte do complexo de Gizé, que também abriga a famosa Esfinge, uma estátua com corpo de leão e rosto humano.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Aproximadamente em que século a.C. viveu Mausolo, homenageado no Mausoléu de Halicarnasso?', '["Século IV a.C.","Século X a.C.","Século I a.C.","Século VIII a.C."]'::jsonb, 0, 'Mausolo governou a região da Cária no século IV a.C., período em que o mausoléu foi construído após sua morte.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Além de Zeus, qual outra grande obra o escultor Fídias é conhecido por ter criado, dentro do Partenon de Atenas?', '["Uma estátua de Atena","Uma estátua de Poseidon","Uma estátua de Apolo","Uma estátua de Afrodite"]'::jsonb, 0, 'Fídias também esculpiu a famosa estátua de Atena Partenos, que ficava dentro do Partenon, na Acrópole de Atenas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Os Jardins Suspensos da Babilônia, segundo a lenda, teriam sido construídos para quem?', '["Para o próprio rei Nabucodonosor II","Para uma esposa do rei, que sentia saudade das paisagens verdes de sua terra natal","Para os sacerdotes do templo principal","Para receber visitantes estrangeiros"]'::jsonb, 1, 'A lenda conta que os jardins foram construídos para aliviar a saudade da esposa do rei, que vinha de uma região montanhosa e verde.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual civilização antiga é responsável pela construção da Grande Pirâmide de Gizé?', '["Os egípcios","Os mesopotâmicos","Os persas","Os fenícios"]'::jsonb, 0, 'A Grande Pirâmide foi construída pelos antigos egípcios durante o período do Império Antigo, há mais de 4.500 anos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo de Ártemis em Éfeso era famoso, entre outras coisas, por seu grande número de quê?', '["Estátuas de ouro","Colunas de mármore","Portas de bronze","Escadarias"]'::jsonb, 1, 'O templo era conhecido por suas numerosas colunas de mármore, muito maior que a maioria dos templos gregos da época.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Mausoléu de Halicarnasso ficou de pé por quantos séculos, aproximadamente, antes de ser destruído?', '["Cerca de 2 séculos","Cerca de 16 séculos","Cerca de 5 séculos","Cerca de 30 séculos"]'::jsonb, 1, 'Construído no século IV a.C., o mausoléu resistiu até ser destruído por terremotos por volta do século XV, ficando de pé por cerca de 1.600-1.900 anos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual figura mitológica adorna, segundo relatos históricos, o topo da Estátua de Zeus em Olímpia?', '["Uma pequena estátua da deusa Nice (vitória)","Uma coroa de louros","Um raio dourado","Uma águia"]'::jsonb, 0, 'Relatos da época descrevem que Zeus segurava, em uma das mãos, uma pequena estátua da deusa Nice, personificação da vitória.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que os arqueólogos utilizam para tentar comprovar a real localização e existência dos Jardins Suspensos da Babilônia?', '["Registros de escritores antigos e escavações na região da Mesopotâmia","Fotografias aéreas modernas","Relatos de viajantes do século XIX apenas","Nenhuma fonte, pois é um mito reconhecido"]'::jsonb, 0, 'Pesquisadores se baseiam em textos de historiadores antigos e em escavações arqueológicas na região da antiga Mesopotâmia para tentar localizar os jardins.');
insert into tourism_questions (question, options, correct_index, explanation) values ('As Sete Maravilhas do Mundo Antigo, em sua maioria, ficavam concentradas em torno de qual região?', '["O Mar Mediterrâneo e o Oriente Médio","A América Central","O Sudeste Asiático","A Europa Ocidental"]'::jsonb, 0, 'As sete maravilhas estavam localizadas na região do Mediterrâneo e do Oriente Médio, área central do mundo conhecido pelos gregos antigos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Em que ano foram eleitas as ''Sete Novas Maravilhas do Mundo Moderno'', em uma votação popular mundial?', '["1999","2007","2012","2015"]'::jsonb, 1, 'A eleição das New7Wonders foi organizada em 2007 por uma fundação suíça, com votação popular pela internet e telefone.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual monumento brasileiro foi eleito uma das Sete Novas Maravilhas do Mundo Moderno em 2007?', '["O Pão de Açúcar","O Cristo Redentor","O Congresso Nacional","O Teatro Amazonas"]'::jsonb, 1, 'O Cristo Redentor, no Rio de Janeiro, foi um dos sete monumentos eleitos na votação popular de 2007.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Cristo Redentor está localizado no topo de qual morro, no Rio de Janeiro?', '["Pão de Açúcar","Corcovado","Morro da Urca","Pedra da Gávea"]'::jsonb, 1, 'A estátua do Cristo Redentor fica no topo do morro do Corcovado, a 710 metros de altitude.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Em que ano o Cristo Redentor foi inaugurado?', '["1922","1931","1945","1960"]'::jsonb, 1, 'O Cristo Redentor foi inaugurado em 12 de outubro de 1931.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Quantos metros de altura tem a estátua do Cristo Redentor, contando com seu pedestal?', '["Cerca de 20 metros","Cerca de 38 metros","Cerca de 60 metros","Cerca de 100 metros"]'::jsonb, 1, 'O Cristo Redentor tem cerca de 38 metros de altura, somando a estátua (30m) e o pedestal (8m).');
insert into tourism_questions (question, options, correct_index, explanation) values ('Quem esculpiu o rosto e as mãos da estátua do Cristo Redentor?', '["O francês Paul Landowski","O brasileiro Heitor da Silva Costa","O italiano Antonio Canova","O romeno Constantin Brâncuși"]'::jsonb, 0, 'O escultor francês Paul Landowski foi responsável pelo desenho do rosto e das mãos da estátua, embora o projeto geral seja do engenheiro Heitor da Silva Costa.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Em qual estilo arquitetônico o Cristo Redentor foi construído?', '["Barroco","Art Déco","Neoclássico","Gótico"]'::jsonb, 1, 'O Cristo Redentor é considerado a maior escultura Art Déco do mundo, estilo característico do início do século XX.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Grande Muralha da China foi eleita uma das Sete Novas Maravilhas do Mundo. Qual dinastia é responsável pela seção mais preservada e visitada da muralha?', '["Dinastia Han","Dinastia Ming","Dinastia Tang","Dinastia Song"]'::jsonb, 1, 'A seção mais bem preservada e mais visitada da Grande Muralha foi construída durante a Dinastia Ming (1368-1644).');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual imperador chinês é tradicionalmente associado ao início da unificação da Grande Muralha da China?', '["Qin Shi Huang","Kublai Khan","Sun Yat-sen","Kangxi"]'::jsonb, 0, 'Qin Shi Huang, primeiro imperador de uma China unificada, ordenou a conexão de muralhas já existentes por volta de 220 a.C.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual era o principal objetivo da construção da Grande Muralha da China?', '["Facilitar o comércio entre regiões","Proteger o território contra invasões do norte","Servir como estrada para caravanas","Demarcar fronteiras religiosas"]'::jsonb, 1, 'A muralha foi construída principalmente como uma fortificação defensiva contra invasões de povos nômades vindos do norte.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A cidade de Petra, uma das Sete Novas Maravilhas do Mundo, está localizada em qual país?', '["Egito","Jordânia","Síria","Líbano"]'::jsonb, 1, 'Petra é uma cidade histórica esculpida na rocha, localizada no sul da Jordânia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual povo antigo é responsável pela construção da cidade de Petra?', '["Os nabateus","Os babilônios","Os fenícios","Os persas"]'::jsonb, 0, 'Petra foi construída pelos nabateus, um povo árabe antigo que a transformou em importante centro comercial de caravanas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Uma característica marcante de Petra é que suas construções foram feitas de que forma?', '["Esculpidas diretamente na rocha arenito","Erguidas com blocos de mármore importado","Construídas inteiramente em madeira","Feitas de tijolos de barro cozido"]'::jsonb, 0, 'Grande parte das edificações de Petra foi esculpida diretamente na rocha arenito avermelhada da região, técnica conhecida como arquitetura rupestre.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Machu Picchu, uma das Sete Novas Maravilhas do Mundo, está localizada em qual país?', '["Bolívia","Peru","Equador","Chile"]'::jsonb, 1, 'Machu Picchu é uma cidadela inca localizada nos Andes peruanos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Machu Picchu é associada a qual civilização antiga?', '["Os astecas","Os maias","Os incas","Os olmecas"]'::jsonb, 2, 'Machu Picchu foi construída pelo Império Inca, provavelmente no século XV.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Quem é o explorador norte-americano creditado por ''redescobrir'' Machu Picchu para o mundo ocidental, em 1911?', '["Hiram Bingham","Howard Carter","Heinrich Schliemann","John Lloyd Stephens"]'::jsonb, 0, 'O historiador e explorador Hiram Bingham apresentou Machu Picchu ao mundo ocidental em 1911, embora moradores locais já conhecessem o local.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Acredita-se que Machu Picchu tenha sido construída como uma espécie de quê para um governante inca?', '["Fortaleza militar","Propriedade/residência real","Prisão","Porto comercial"]'::jsonb, 1, 'A hipótese mais aceita é que Machu Picchu tenha sido construída como uma propriedade real para o imperador inca Pachacuti.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Chichén Itzá, uma das Sete Novas Maravilhas do Mundo, está localizada em qual país?', '["Guatemala","México","Honduras","Belize"]'::jsonb, 1, 'Chichén Itzá é um sítio arqueológico maia localizado na península de Yucatán, no México.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Chichén Itzá foi construída por qual civilização mesoamericana?', '["Os astecas","Os maias","Os incas","Os toltecas isoladamente"]'::jsonb, 1, 'Chichén Itzá foi um importante centro da civilização maia, com influências posteriores de outros povos como os toltecas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Como se chama a famosa pirâmide central de Chichén Itzá, dedicada a uma divindade maia?', '["El Castillo (Templo de Kukulkán)","Templo do Sol","Pirâmide da Lua","Templo dos Guerreiros"]'::jsonb, 0, 'A pirâmide principal, conhecida como El Castillo, é dedicada ao deus serpente emplumada Kukulkán.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Coliseu de Roma, uma das Sete Novas Maravilhas do Mundo, está localizado em qual país?', '["Grécia","Itália","Espanha","França"]'::jsonb, 1, 'O Coliseu está localizado no centro de Roma, na Itália.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Para que finalidade o Coliseu de Roma era originalmente utilizado?', '["Templo religioso","Palácio imperial","Arena para espetáculos públicos, como lutas de gladiadores","Biblioteca pública"]'::jsonb, 2, 'O Coliseu era um anfiteatro usado para espetáculos públicos, incluindo combates de gladiadores e caçadas de animais.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Em que período histórico o Coliseu de Roma foi construído?', '["Império Romano, no século I d.C.","Idade Média, no século X","Renascimento, no século XV","Grécia Antiga, no século V a.C."]'::jsonb, 0, 'O Coliseu foi construído durante o Império Romano, iniciado sob o imperador Vespasiano e concluído por Tito, por volta de 80 d.C.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Aproximadamente quantas pessoas o Coliseu de Roma podia comportar em sua capacidade original?', '["Cerca de 5 mil","Cerca de 50 mil","Cerca de 200 mil","Cerca de 500"]'::jsonb, 1, 'Estima-se que o Coliseu tinha capacidade para acomodar entre 50 e 80 mil espectadores.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Taj Mahal, uma das Sete Novas Maravilhas do Mundo, está localizado em qual cidade indiana?', '["Nova Deli","Agra","Mumbai","Jaipur"]'::jsonb, 1, 'O Taj Mahal está localizado na cidade de Agra, no norte da Índia, às margens do rio Yamuna.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Taj Mahal foi construído pelo imperador mogol Shah Jahan em homenagem a quem?', '["Sua mãe","Sua esposa, Mumtaz Mahal","Seu pai","Um líder religioso"]'::jsonb, 1, 'O Taj Mahal foi construído como mausoléu para Mumtaz Mahal, esposa favorita do imperador Shah Jahan, falecida em 1631.');
insert into tourism_questions (question, options, correct_index, explanation) values ('De qual material é feita, predominantemente, a estrutura externa do Taj Mahal?', '["Granito cinza","Mármore branco","Arenito vermelho","Calcário bruto"]'::jsonb, 1, 'O Taj Mahal é famoso por sua estrutura de mármore branco, que muda de tonalidade conforme a luz do dia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Em que ano, aproximadamente, teve início a construção do Taj Mahal?', '["1526","1632","1748","1857"]'::jsonb, 1, 'A construção do Taj Mahal começou por volta de 1632, a mando do imperador Shah Jahan.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Quanto tempo, aproximadamente, levou a construção do mausoléu principal do Taj Mahal?', '["Cerca de 2 anos","Cerca de 16 anos","Cerca de 50 anos","Cerca de 100 anos"]'::jsonb, 1, 'O corpo principal do mausoléu foi concluído em cerca de 16 anos (1632-1648), embora todo o complexo tenha levado ainda mais tempo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Em que ano a Grande Pirâmide de Gizé foi adicionada como ''candidata honorária'' à lista das Sete Novas Maravilhas do Mundo?', '["2007","1999","2015","Ela nunca foi incluída, mesmo honorariamente"]'::jsonb, 0, 'Como já era considerada uma das maravilhas originais da Antiguidade, a Grande Pirâmide de Gizé recebeu o status de candidata honorária em 2007, fora da votação popular.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A organização responsável por eleger as Sete Novas Maravilhas do Mundo em 2007 se chama como?', '["UNESCO","New7Wonders Foundation","National Geographic Society","Organização Mundial do Turismo"]'::jsonb, 1, 'A votação foi promovida pela New7Wonders Foundation, uma organização suíça, e não tem vínculo oficial com a UNESCO.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Quantos monumentos concorreram na etapa final da votação das Sete Novas Maravilhas do Mundo, em 2007?', '["7","14","21","50"]'::jsonb, 2, 'A lista final de candidatos incluía 21 monumentos, dos quais 7 foram eleitos pelo público.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Cristo Redentor recebeu, em 2012, um reconhecimento importante da UNESCO. Qual foi?', '["Foi declarado Patrimônio Mundial da Humanidade","Foi eleito uma das sete maravilhas naturais","Recebeu um prêmio de arquitetura moderna","Foi tombado como monumento militar"]'::jsonb, 0, 'Em 2012, a UNESCO reconheceu o Cristo Redentor e a paisagem do Rio de Janeiro como Patrimônio Mundial da Humanidade.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O sistema usado para transportar materiais de construção até o topo do morro do Corcovado, durante a obra do Cristo Redentor, foi:', '["Um teleférico de carga","Um trem/bondinho sobre trilhos","Helicópteros","Carroças puxadas por bois"]'::jsonb, 1, 'Um sistema de trem (o mesmo trilho que ainda leva turistas hoje) foi utilizado para transportar materiais e trabalhadores até o topo do Corcovado.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Petra também é conhecida por qual apelido, relacionado à cor de suas construções?', '["''A Cidade Branca''","''A Cidade Rosa''","''A Cidade Dourada''","''A Cidade Negra''"]'::jsonb, 1, 'Petra é apelidada de ''Cidade Rosa'' por causa da tonalidade avermelhada/rosada da rocha arenito em que foi esculpida.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual monumento das Sete Novas Maravilhas do Mundo é o único localizado no continente asiático entre China, Jordânia e Índia, além da própria Grande Muralha?', '["O Taj Mahal, na Índia","O Coliseu, na Itália","Machu Picchu, no Peru","O Cristo Redentor, no Brasil"]'::jsonb, 0, 'Entre as sete, o Taj Mahal (Índia), Petra (Jordânia) e a Grande Muralha (China) estão no continente asiático.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Machu Picchu está situada a que altitude aproximada, nos Andes peruanos?', '["Cerca de 500 metros","Cerca de 2.430 metros","Cerca de 5.000 metros","Ao nível do mar"]'::jsonb, 1, 'Machu Picchu está a aproximadamente 2.430 metros de altitude, entre as montanhas dos Andes.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual técnica de construção os incas utilizaram em Machu Picchu, encaixando pedras sem uso de argamassa?', '["Alvenaria em seco (encaixe de pedras)","Concreto armado","Tijolos vazados","Estruturas de madeira revestidas de pedra"]'::jsonb, 0, 'Os incas utilizavam uma técnica de encaixe preciso de pedras sem argamassa, o que contribuiu para a resistência das construções a terremotos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Por que os espanhóis nunca encontraram Machu Picchu durante a colonização da América?', '["Porque ela ficava escondida em uma região de difícil acesso na montanha","Porque tinha um exército que a defendia","Porque ela ficava no fundo de uma caverna","Porque foi construída depois da colonização"]'::jsonb, 0, 'A localização remota e de difícil acesso, entre montanhas, fez com que Machu Picchu passasse despercebida pelos colonizadores espanhóis.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que significa ''Chichén Itzá'' na língua maia?', '["''Cidade das Serpentes''","''Na boca do poço dos itzás''","''Templo do Sol''","''Grande Pirâmide''"]'::jsonb, 1, 'O nome ''Chichén Itzá'' significa aproximadamente ''na boca do poço dos itzás'', referência aos poços naturais (cenotes) sagrados do local.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Coliseu de Roma também é conhecido por qual outro nome, referente ao imperador que o mandou construir?', '["Anfiteatro Flaviano","Templo de César","Arena Juliana","Circo Augusto"]'::jsonb, 0, 'O Coliseu também é chamado de Anfiteatro Flaviano, em referência à dinastia Flávia, que iniciou sua construção.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Além do Cristo Redentor, qual outro ponto turístico famoso do Rio de Janeiro é um morro com bondinho?', '["Corcovado","Pão de Açúcar","Pedra da Gávea","Morro de Santa Teresa"]'::jsonb, 1, 'O Pão de Açúcar é um morro icônico do Rio de Janeiro, acessado por um bondinho (teleférico) inaugurado em 1912.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Em que cidade brasileira está localizado o Teatro Amazonas, famoso por sua cúpula colorida?', '["Belém","Manaus","Porto Velho","Boa Vista"]'::jsonb, 1, 'O Teatro Amazonas fica em Manaus, capital do Amazonas, e foi construído durante o ciclo econômico da borracha.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Em que período histórico o Teatro Amazonas foi construído?', '["Durante o ciclo da borracha, no final do século XIX","Durante o período colonial, no século XVII","Após a Segunda Guerra Mundial","Durante o Império, no início do século XIX"]'::jsonb, 0, 'O Teatro Amazonas foi inaugurado em 1896, financiado pela riqueza gerada pelo ciclo econômico da borracha na Amazônia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual arquiteto brasileiro é o principal responsável pelo desenho dos prédios do Congresso Nacional, em Brasília?', '["Lúcio Costa","Oscar Niemeyer","Burle Marx","Ramos de Azevedo"]'::jsonb, 1, 'Oscar Niemeyer foi o arquiteto responsável pelo projeto arquitetônico dos principais edifícios de Brasília, incluindo o Congresso Nacional.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Quem foi o urbanista responsável pelo plano geral (plano piloto) da cidade de Brasília?', '["Oscar Niemeyer","Lúcio Costa","Roberto Burle Marx","Athos Bulcão"]'::jsonb, 1, 'Lúcio Costa venceu o concurso para o plano urbanístico de Brasília, conhecido como Plano Piloto.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Em que ano Brasília foi inaugurada como capital do Brasil?', '["1950","1960","1975","1988"]'::jsonb, 1, 'Brasília foi inaugurada em 21 de abril de 1960, durante o governo de Juscelino Kubitschek.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O centro histórico de qual cidade mineira é famoso por sua arquitetura colonial e barroca, sendo Patrimônio Mundial da UNESCO?', '["Belo Horizonte","Ouro Preto","Uberlândia","Juiz de Fora"]'::jsonb, 1, 'Ouro Preto, antiga capital de Minas Gerais, preserva um dos mais importantes conjuntos de arquitetura colonial barroca do Brasil.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual escultor e entalhador brasileiro, conhecido como Aleijadinho, é famoso por suas obras em Ouro Preto e outras cidades mineiras?', '["Antônio Francisco Lisboa","Mestre Valentim","Cândido Portinari","Victor Meirelles"]'::jsonb, 0, 'Antônio Francisco Lisboa, o Aleijadinho, foi um dos maiores escultores do barroco brasileiro, autor de obras como os Profetas de Congonhas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Em qual cidade mineira ficam as famosas esculturas dos ''Profetas'', obra do Aleijadinho?', '["Congonhas","Ouro Preto","Tiradentes","Mariana"]'::jsonb, 0, 'As esculturas dos Doze Profetas, uma das obras-primas do Aleijadinho, ficam no Santuário de Bom Jesus de Matosinhos, em Congonhas (MG).');
insert into tourism_questions (question, options, correct_index, explanation) values ('O bairro do Pelourinho, com seu conjunto de casarões coloridos e igrejas históricas, fica em qual capital brasileira?', '["Salvador","Recife","São Luís","Fortaleza"]'::jsonb, 0, 'O Pelourinho é o centro histórico de Salvador, na Bahia, reconhecido como Patrimônio Mundial pela UNESCO.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual monumento localizado em São Paulo homenageia os pioneiros que desbravaram o interior do Brasil?', '["O Monumento às Bandeiras","O Obelisco do Ibirapuera","O Marco Zero","O Farol do Comércio"]'::jsonb, 0, 'O Monumento às Bandeiras, esculpido por Victor Brecheret, homenageia os bandeirantes e fica no Parque Ibirapuera, em São Paulo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Quem foi o escultor responsável pelo Monumento às Bandeiras, em São Paulo?', '["Victor Brecheret","Aleijadinho","Bruno Giorgi","Rodin"]'::jsonb, 0, 'O Monumento às Bandeiras foi criado pelo escultor ítalo-brasileiro Victor Brecheret, concluído em 1953.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Museu do Amanhã, com sua arquitetura futurista à beira-mar, fica em qual cidade brasileira?', '["Rio de Janeiro","São Paulo","Recife","Florianópolis"]'::jsonb, 0, 'O Museu do Amanhã fica na região portuária do Rio de Janeiro, com projeto do arquiteto espanhol Santiago Calatrava.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Quem projetou o Museu do Amanhã, no Rio de Janeiro?', '["Santiago Calatrava","Oscar Niemeyer","Zaha Hadid","Renzo Piano"]'::jsonb, 0, 'O museu foi projetado pelo arquiteto espanhol Santiago Calatrava, conhecido por seus projetos de arquitetura futurista.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Marco das Três Fronteiras, ponto turístico que reúne Brasil, Argentina e Paraguai, fica em qual cidade brasileira?', '["Foz do Iguaçu","Corumbá","Uruguaiana","Ponta Porã"]'::jsonb, 0, 'O Marco das Três Fronteiras fica em Foz do Iguaçu (PR), onde os territórios de Brasil, Argentina e Paraguai se encontram.');
insert into tourism_questions (question, options, correct_index, explanation) values ('As Cataratas do Iguaçu, uma das principais atrações naturais do Brasil, ficam na divisa com qual país?', '["Uruguai","Argentina","Bolívia","Peru"]'::jsonb, 1, 'As Cataratas do Iguaçu ficam na fronteira entre o Brasil (Paraná) e a Argentina.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual é o nome do famoso Mosteiro de São Bento, importante exemplo de arquitetura colonial, presente em várias capitais brasileiras?', '["Mosteiro de São Bento","Convento da Penha","Basílica de Nazaré","Catedral de Brasília"]'::jsonb, 0, 'O Mosteiro de São Bento é uma ordem religiosa com edificações históricas importantes em cidades como Rio de Janeiro, Salvador e Olinda.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Catedral Metropolitana de Brasília, com seu formato de coroa de espinhos, foi projetada por quem?', '["Oscar Niemeyer","Lúcio Costa","Roberto Burle Marx","Ramos de Azevedo"]'::jsonb, 0, 'A Catedral de Brasília é outra obra de Oscar Niemeyer, com uma estrutura circular composta por 16 colunas curvas de concreto.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Em que material a estrutura da Catedral de Brasília é predominantemente feita?', '["Vidro e concreto","Mármore maciço","Madeira e tijolo","Aço inoxidável apenas"]'::jsonb, 0, 'A catedral combina uma estrutura de concreto com grandes painéis de vidro colorido entre as colunas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O centro histórico de qual cidade maranhense é conhecido por seus azulejos portugueses e casarões coloniais, sendo Patrimônio Mundial?', '["São Luís","Teresina","Imperatriz","Caxias"]'::jsonb, 0, 'São Luís, capital do Maranhão, tem seu centro histórico reconhecido pela UNESCO por sua arquitetura colonial portuguesa e azulejaria.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual cidade histórica de Minas Gerais, tombada como patrimônio, é conhecida por suas ladeiras e igrejas barrocas, tendo sido palco da Inconfidência Mineira?', '["Diamantina","Ouro Preto","Tiradentes","Mariana"]'::jsonb, 1, 'Ouro Preto foi palco de importantes eventos históricos como a Inconfidência Mineira, movimento pela independência do Brasil no século XVIII.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Palácio do Planalto, sede do governo federal brasileiro, está localizado em qual cidade?', '["Rio de Janeiro","Brasília","São Paulo","Salvador"]'::jsonb, 1, 'O Palácio do Planalto, sede da Presidência da República, fica em Brasília e também foi projetado por Oscar Niemeyer.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Farol da Barra, um dos mais antigos faróis do Brasil, está localizado em qual cidade?', '["Salvador","Recife","Natal","Fortaleza"]'::jsonb, 0, 'O Farol da Barra fica em Salvador, na Bahia, e é considerado um dos faróis mais antigos das Américas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Basílica de Nossa Senhora de Nazaré, importante monumento religioso, fica em qual capital brasileira?', '["Belém","Manaus","Palmas","Macapá"]'::jsonb, 0, 'A Basílica de Nazaré fica em Belém do Pará e é palco do Círio de Nazaré, uma das maiores procissões religiosas do mundo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Theatro Municipal, importante casa de espetáculos inspirada na Ópera de Paris, fica em qual cidade brasileira?', '["São Paulo","Rio de Janeiro","Ambas têm um Theatro Municipal famoso","Porto Alegre"]'::jsonb, 2, 'Tanto São Paulo quanto o Rio de Janeiro possuem um famoso Theatro Municipal, ambos inspirados em teatros europeus como a Ópera de Paris.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual conjunto arquitetônico colonial em Diamantina (MG) é reconhecido pela UNESCO como Patrimônio Mundial?', '["O centro histórico da cidade","Apenas a Praça da Sé","O Museu do Diamante isoladamente","A Estação Ferroviária"]'::jsonb, 0, 'O centro histórico de Diamantina foi declarado Patrimônio Mundial pela UNESCO em 1999, por seu conjunto arquitetônico colonial bem preservado.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Elevador Lacerda, importante marco urbano que liga a cidade alta à cidade baixa, fica em qual cidade?', '["Salvador","Recife","São Luís","Vitória"]'::jsonb, 0, 'O Elevador Lacerda, inaugurado em 1873, conecta o Centro Histórico (cidade alta) ao Comércio (cidade baixa) em Salvador.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Palácio de Belas Artes, importante edifício histórico do Rio de Janeiro, foi inspirado em qual estilo?', '["Estilo eclético/neoclássico europeu","Modernismo brutalista","Arquitetura indígena","Art Nouveau exclusivamente"]'::jsonb, 0, 'O Palácio de Belas Artes, no centro do Rio, segue um estilo eclético inspirado em palácios europeus do início do século XX.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Ponte Hercílio Luz, importante marco arquitetônico do sul do Brasil, está localizada em qual cidade?', '["Florianópolis","Curitiba","Porto Alegre","Joinville"]'::jsonb, 0, 'A Ponte Hercílio Luz liga a ilha de Santa Catarina ao continente, em Florianópolis, e é um símbolo da cidade.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Monumento Nacional aos Pracinhas, que homenageia os soldados brasileiros da Segunda Guerra Mundial, fica em qual cidade?', '["Rio de Janeiro","Brasília","São Paulo","Porto Alegre"]'::jsonb, 0, 'O Monumento aos Pracinhas fica no Aterro do Flamengo, no Rio de Janeiro, homenageando os combatentes da Força Expedicionária Brasileira.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Praça dos Três Poderes, que reúne os prédios do Executivo, Legislativo e Judiciário, fica em qual cidade?', '["Brasília","Rio de Janeiro","Salvador","São Paulo"]'::jsonb, 0, 'A Praça dos Três Poderes, em Brasília, reúne o Palácio do Planalto, o Congresso Nacional e o Supremo Tribunal Federal.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual escultura, também de Oscar Niemeyer, é um símbolo do Memorial da América Latina, em São Paulo?', '["A mão com uma mancha vermelha","O Monumento às Bandeiras","A Torre de TV","O Obelisco"]'::jsonb, 0, 'A escultura da mão sangrando, símbolo do Memorial da América Latina, representa a dor dos povos latino-americanos e é obra de Niemeyer.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Estação da Luz, importante marco arquitetônico ferroviário, está localizada em qual cidade?', '["São Paulo","Rio de Janeiro","Curitiba","Salvador"]'::jsonb, 0, 'A Estação da Luz, com sua arquitetura de influência inglesa, é um dos principais marcos históricos de São Paulo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que caracteriza a arquitetura colonial das cidades históricas de Minas Gerais, como Ouro Preto e Tiradentes?', '["O uso de aço e vidro","O estilo barroco, com igrejas ricamente ornamentadas","Arranha-céus modernos","Construções indígenas tradicionais"]'::jsonb, 1, 'As cidades históricas mineiras são marcadas pelo estilo barroco colonial, especialmente visível em suas igrejas e capelas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Palácio da Alvorada, residência oficial do presidente da República, foi projetado por qual arquiteto?', '["Oscar Niemeyer","Lúcio Costa","Ramos de Azevedo","Burle Marx"]'::jsonb, 0, 'O Palácio da Alvorada, em Brasília, foi um dos primeiros grandes projetos de Oscar Niemeyer para a nova capital.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A cidade de Olinda, com seu centro histórico colonial colorido, fica em qual estado?', '["Pernambuco","Bahia","Paraíba","Alagoas"]'::jsonb, 0, 'Olinda, no estado de Pernambuco, é famosa por seu centro histórico colonial e é Patrimônio Mundial da UNESCO.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que motivou a construção do Teatro Amazonas em Manaus, no final do século XIX?', '["A riqueza gerada pela exportação de látex da borracha","A necessidade de um espaço para eventos políticos","O turismo já consolidado na região","Uma doação da coroa portuguesa"]'::jsonb, 0, 'O teatro foi financiado pela riqueza dos seringalistas durante o auge do ciclo econômico da borracha na Amazônia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Palácio Rio Negro, importante prédio histórico, está localizado em qual cidade?', '["Manaus","Belém","Porto Velho","Rio Branco"]'::jsonb, 0, 'O Palácio Rio Negro, antiga residência de um barão da borracha, fica em Manaus e hoje funciona como centro cultural.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual é o principal material usado na construção das fachadas de muitos casarões históricos de São Luís (MA)?', '["Azulejos portugueses","Mármore de Carrara","Concreto armado","Bambu"]'::jsonb, 0, 'São Luís é conhecida por suas fachadas revestidas com azulejos de origem portuguesa, característica que marca a arquitetura da cidade.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Palácio Itamaraty, sede do Ministério das Relações Exteriores, fica em qual cidade?', '["Brasília","Rio de Janeiro","São Paulo","Belo Horizonte"]'::jsonb, 0, 'O Palácio Itamaraty, também projetado por Oscar Niemeyer, é a sede do Ministério das Relações Exteriores em Brasília.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Fortaleza de São José de Macapá, importante construção militar histórica, está localizada em qual capital?', '["Macapá","Belém","Boa Vista","Rio Branco"]'::jsonb, 0, 'A Fortaleza de São José de Macapá é um dos principais monumentos históricos militares do Amapá, construída no século XVIII.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que representa arquitetonicamente o formato da Catedral de Brasília, com suas colunas curvas apontando para o céu?', '["Uma coroa de espinhos","Uma nave espacial","Um vulcão em erupção","Uma flor de lótus"]'::jsonb, 0, 'O formato circular com colunas inclinadas é geralmente associado a uma coroa de espinhos, símbolo cristão da paixão de Cristo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Convento de Santo Antônio, importante marco religioso do Rio de Janeiro, está localizado onde?', '["No centro da cidade, próximo à Cinelândia","Na Barra da Tijuca","Em Niterói","No bairro de Copacabana"]'::jsonb, 0, 'O Convento de Santo Antônio é um dos mais antigos conventos do Brasil, localizado no centro do Rio de Janeiro.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A famosa escadaria colorida conhecida como Escadaria Selarón fica em qual bairro do Rio de Janeiro?', '["Lapa/Santa Teresa","Copacabana","Barra da Tijuca","Ipanema"]'::jsonb, 0, 'A Escadaria Selarón, decorada com azulejos coloridos pelo artista chileno Jorge Selarón, liga os bairros da Lapa e Santa Teresa.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Sambódromo, palco do desfile das escolas de samba do Rio de Janeiro, também foi projetado por qual arquiteto?', '["Oscar Niemeyer","Lúcio Costa","Roberto Burle Marx","Affonso Reidy"]'::jsonb, 0, 'O Sambódromo do Rio de Janeiro, inaugurado em 1984, é outra obra de Oscar Niemeyer.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Casa das Onze Janelas, importante prédio histórico à beira do rio, fica em qual capital?', '["Belém","Manaus","São Luís","Macapá"]'::jsonb, 0, 'A Casa das Onze Janelas fica no bairro da Cidade Velha, em Belém, e hoje abriga um centro cultural.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Museu de Arte de São Paulo (MASP), reconhecido por sua estrutura suspensa em vãos livres, foi projetado por quem?', '["Lina Bo Bardi","Oscar Niemeyer","Ramos de Azevedo","Paulo Mendes da Rocha"]'::jsonb, 0, 'O MASP, com seu icônico vão livre suportado por grandes vigas vermelhas, foi projetado pela arquiteta ítalo-brasileira Lina Bo Bardi.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Ponte JK, conhecida por seu design moderno com arcos que cruzam o tabuleiro, está localizada em qual cidade?', '["Brasília","Belo Horizonte","Curitiba","Goiânia"]'::jsonb, 0, 'A Ponte JK cruza o Lago Paranoá em Brasília e é conhecida por seu design contemporâneo premiado internacionalmente.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Forte de Copacabana, importante construção militar histórica, está localizado em qual cidade?', '["Rio de Janeiro","Niterói","Salvador","Fortaleza"]'::jsonb, 0, 'O Forte de Copacabana, construído no início do século XX, fica na ponta da praia de Copacabana, no Rio de Janeiro.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Casa de Câmara e Cadeia, um dos edifícios históricos mais antigos preservados em Minas Gerais, fica em qual cidade?', '["Ouro Preto","Belo Horizonte","Uberaba","Juiz de Fora"]'::jsonb, 0, 'A antiga Casa de Câmara e Cadeia de Ouro Preto, hoje Museu da Inconfidência, é um marco da arquitetura colonial mineira.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Santuário Fushimi Inari, famoso por seus milhares de portões torii vermelhos, está localizado em qual cidade japonesa?', '["Tóquio","Quioto","Osaka","Nagoya"]'::jsonb, 1, 'O Santuário Fushimi Inari fica em Quioto e é famoso por seu caminho formado por milhares de portões torii vermelhos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A qual divindade é dedicado o Santuário Fushimi Inari, no Japão?', '["Inari, divindade do arroz e da prosperidade","Amaterasu, deusa do sol","Hachiman, deus da guerra","Buda"]'::jsonb, 0, 'O santuário é dedicado a Inari, divindade xintoísta associada ao arroz, à agricultura e à prosperidade nos negócios.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que são os portões vermelhos que formam os famosos túneis do Santuário Fushimi Inari?', '["Torii","Pagodes","Estupas","Mandalas"]'::jsonb, 0, 'Os portões chamados torii marcam a entrada para espaços sagrados na tradição xintoísta japonesa.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Castelo de Himeji, um dos mais bem preservados do Japão, também é conhecido pelo apelido de:', '["Castelo Dourado","Castelo da Garça Branca","Castelo do Dragão","Castelo de Cristal"]'::jsonb, 1, 'O Castelo de Himeji é apelidado de ''Castelo da Garça Branca'' (Shirasagijo) por sua aparência branca e elegante.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Em qual período da história japonesa o Castelo de Himeji, em sua forma atual, foi construído?', '["Período Edo, início do século XVII","Período Meiji, no século XIX","Segunda Guerra Mundial","Período Nara, no século VIII"]'::jsonb, 0, 'A estrutura atual do Castelo de Himeji data principalmente do início do período Edo, por volta de 1609.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Pavilhão Dourado, ou Kinkaku-ji, está localizado em qual cidade japonesa?', '["Tóquio","Quioto","Yokohama","Sapporo"]'::jsonb, 1, 'O Kinkaku-ji, ou Pavilhão Dourado, é um templo zen budista em Quioto, revestido com folhas de ouro.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Por que o Kinkaku-ji é chamado de ''Pavilhão Dourado''?', '["Porque fica ao lado de minas de ouro","Porque seus andares superiores são revestidos com folhas de ouro","Porque foi construído por um imperador chamado ''Dourado''","Porque brilha ao amanhecer, por uma ilusão de ótica"]'::jsonb, 1, 'Os dois andares superiores do pavilhão são cobertos com folhas de ouro, o que lhe dá o nome e a aparência dourada característica.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Grande Buda de Nara, uma das maiores estátuas de bronze do Japão, está localizado dentro de qual templo?', '["Todai-ji","Kinkaku-ji","Sensoji","Kiyomizu-dera"]'::jsonb, 0, 'O Grande Buda de Nara está abrigado no templo Todai-ji, na cidade de Nara.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O templo Todai-ji, em Nara, é reconhecido por abrigar qual das maiores estruturas do tipo no mundo?', '["O maior edifício de madeira do mundo","A maior pagode do mundo","O maior jardim zen do mundo","O maior mosteiro budista da Ásia"]'::jsonb, 0, 'O Salão Principal (Daibutsuden) do Todai-ji é considerado um dos maiores edifícios de madeira do mundo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Santuário Itsukushima, famoso por seu ''torii flutuante'', está localizado em qual ilha japonesa?', '["Ilha de Miyajima","Ilha de Hokkaido","Ilha de Okinawa","Ilha de Sado"]'::jsonb, 0, 'O Santuário Itsukushima, com seu famoso torii que parece flutuar na água durante a maré alta, fica na ilha de Miyajima.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que causa o efeito visual de o torii do Santuário Itsukushima parecer ''flutuar'' sobre a água?', '["A maré alta cobrindo a base do portão","Um sistema de espelhos","Ilusão criada por luzes artificiais","O portão realmente flutua sobre boias"]'::jsonb, 0, 'Durante a maré alta, a água do mar cobre a base do torii, criando a impressão de que ele está flutuando.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Monte Fuji, a montanha mais alta e um dos símbolos mais reconhecidos do Japão, é classificado geologicamente como o quê?', '["Um vulcão ativo","Uma cordilheira de granito","Uma formação de calcário","Uma cratera de meteorito"]'::jsonb, 0, 'O Monte Fuji é um estratovulcão, considerado ativo, embora sua última erupção registrada tenha sido em 1707.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Torre de Tóquio, inspirada em outro monumento famoso, é uma réplica estilizada de qual construção?', '["Torre Eiffel, de Paris","Big Ben, de Londres","Torre de Pisa, da Itália","Empire State Building, de Nova York"]'::jsonb, 0, 'A Torre de Tóquio foi inspirada na Torre Eiffel de Paris, embora seja ligeiramente mais alta e pintada de laranja e branco.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual é a principal função da Torre de Tóquio, além de atração turística?', '["Transmissão de sinais de rádio e televisão","Observatório astronômico","Depósito de água da cidade","Sede do governo japonês"]'::jsonb, 0, 'Além de ponto turístico, a Torre de Tóquio funciona como estrutura de transmissão de sinais de rádio e TV.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo Sensoji, o mais antigo templo budista de Tóquio, está localizado em qual bairro?', '["Asakusa","Shibuya","Shinjuku","Ginza"]'::jsonb, 0, 'O Sensoji, templo budista dedicado à deusa Kannon, fica no tradicional bairro de Asakusa, em Tóquio.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O portão de entrada do Templo Sensoji, famoso por sua enorme lanterna vermelha, é chamado de:', '["Kaminarimon (Portão do Trovão)","Torii Dourado","Portão da Serenidade","Portão dos Mil Budas"]'::jsonb, 0, 'O Kaminarimon, ou ''Portão do Trovão'', é a entrada icônica do Sensoji, reconhecível por sua grande lanterna de papel vermelha.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Palácio Imperial de Tóquio, residência da família imperial japonesa, foi construído sobre as ruínas de qual antiga fortaleza?', '["O Castelo de Edo","O Castelo de Osaka","O Castelo de Nagoya","O Castelo de Nijo"]'::jsonb, 0, 'O Palácio Imperial foi erguido sobre o antigo Castelo de Edo, sede do governo dos xoguns Tokugawa.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Castelo de Osaka, um dos mais famosos do Japão, foi originalmente construído por qual líder histórico?', '["Toyotomi Hideyoshi","Tokugawa Ieyasu","Oda Nobunaga","Imperador Meiji"]'::jsonb, 0, 'O Castelo de Osaka foi originalmente construído sob ordens de Toyotomi Hideyoshi, no final do século XVI.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo Kiyomizu-dera, conhecido por sua grande varanda de madeira sustentada sem pregos, fica em qual cidade?', '["Quioto","Tóquio","Osaka","Kobe"]'::jsonb, 0, 'O Kiyomizu-dera, famoso por sua estrutura de madeira erguida sem o uso de pregos, está localizado em Quioto.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O nome ''Kiyomizu-dera'' está relacionado a qual elemento natural presente no templo?', '["Uma cachoeira de água considerada pura","Uma floresta de bambu","Um vulcão adormecido","Um lago sagrado congelado"]'::jsonb, 0, 'O nome significa ''templo da água pura'', referência a uma cachoeira dentro do complexo, considerada sagrada.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Parque Memorial da Paz de Hiroshima, com sua Cúpula da Bomba Atômica preservada, homenageia qual evento histórico?', '["O bombardeio atômico de Hiroshima em 1945","O terremoto de Kobe de 1995","A Segunda Guerra Sino-Japonesa","O Grande Terremoto de Kanto de 1923"]'::jsonb, 0, 'O parque e a Cúpula da Bomba Atômica preservam a memória do bombardeio atômico que atingiu Hiroshima em 6 de agosto de 1945.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Cúpula da Bomba Atômica, em Hiroshima, foi mantida em ruínas propositalmente com qual objetivo?', '["Servir como lembrança permanente dos horrores da guerra nuclear","Por falta de recursos para reconstrução","Como parte de um projeto arquitetônico moderno","Porque nunca foi identificada a estrutura original"]'::jsonb, 0, 'As ruínas foram preservadas intencionalmente como um símbolo e lembrança permanente contra as armas nucleares.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Grande Buda de Kamakura, uma das estátuas mais famosas do Japão, fica ao ar livre em qual cidade?', '["Kamakura","Nara","Nikko","Kanazawa"]'::jsonb, 0, 'O Grande Buda de Kamakura, feito em bronze, fica ao ar livre desde que seu templo original foi destruído por um tsunami no século XV.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Os santuários de Nikko, incluindo o famoso Toshogu, homenageiam qual figura histórica japonesa?', '["O xogum Tokugawa Ieyasu","O imperador Meiji","O samurai Miyamoto Musashi","O monge Kukai"]'::jsonb, 0, 'O Santuário Toshogu, em Nikko, foi construído para homenagear Tokugawa Ieyasu, fundador do xogunato Tokugawa.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Castelo de Matsumoto, também conhecido como ''Castelo do Corvo'' por sua cor escura, fica em qual região do Japão?', '["Prefeitura de Nagano","Prefeitura de Okinawa","Prefeitura de Hokkaido","Prefeitura de Fukuoka"]'::jsonb, 0, 'O Castelo de Matsumoto, um dos castelos originais mais antigos do Japão, fica na prefeitura de Nagano.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Jardim Kenrokuen, um dos três jardins mais famosos do Japão, está localizado em qual cidade?', '["Kanazawa","Quioto","Nagoya","Sendai"]'::jsonb, 0, 'O Kenrokuen, considerado um dos três jardins paisagísticos mais belos do Japão, fica na cidade de Kanazawa.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que significa o nome ''Kenrokuen'', dado a um dos mais famosos jardins japoneses?', '["''Jardim das seis qualidades combinadas''","''Jardim do imperador dourado''","''Jardim das mil flores''","''Jardim do dragão adormecido''"]'::jsonb, 0, 'O nome faz referência a seis qualidades ideais que um jardim clássico japonês deveria reunir, segundo a tradição paisagística chinesa.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo Ryoan-ji, em Quioto, é famoso mundialmente por qual tipo de jardim?', '["Um jardim de pedras zen (jardim seco)","Um jardim de cerejeiras","Um labirinto de bambu","Um jardim aquático com carpas coloridas"]'::jsonb, 0, 'O Ryoan-ji é célebre por seu jardim de pedras (karesansui), um dos exemplos mais famosos de jardim zen seco do Japão.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Floresta de Bambu de Arashiyama, famosa atração natural, está localizada em qual cidade?', '["Quioto","Tóquio","Osaka","Hiroshima"]'::jsonb, 0, 'A Floresta de Bambu de Arashiyama fica na região oeste de Quioto e é um dos pontos turísticos naturais mais fotografados do Japão.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Castelo de Nagoya, reconhecido por seus dois grandes golfinhos dourados no topo, fica em qual cidade?', '["Nagoya","Osaka","Kobe","Sendai"]'::jsonb, 0, 'O Castelo de Nagoya é famoso por suas esculturas douradas em forma de ''shachihoko'' (uma criatura mítica com corpo de peixe) no topo do telhado.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O templo budista do Monte Koya (Koyasan) é um importante centro de qual escola do budismo japonês?', '["Budismo Shingon","Budismo Zen Soto","Budismo Nichiren","Budismo Jodo Shinshu"]'::jsonb, 0, 'O Monte Koya é o centro histórico do budismo Shingon, fundado pelo monge Kukai no século IX.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Ponte Kintai, famosa por seus cinco arcos de madeira, está localizada em qual cidade japonesa?', '["Iwakuni","Nagasaki","Kumamoto","Matsuyama"]'::jsonb, 0, 'A Ponte Kintai, com seus cinco arcos de madeira sobre o rio Nishiki, fica na cidade de Iwakuni.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que caracteriza a arquitetura tradicional dos torii, portões sagrados presentes em santuários xintoístas japoneses?', '["Marcam a transição entre o espaço comum e o sagrado","Servem apenas como decoração sem significado religioso","São usados exclusivamente em templos budistas","Representam fronteiras entre cidades"]'::jsonb, 0, 'Os torii marcam simbolicamente a passagem do mundo comum para o espaço sagrado de um santuário xintoísta.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo Byodo-in, com seu famoso ''Salão da Fênix'' retratado na moeda japonesa de 10 ienes, fica em qual cidade?', '["Uji","Quioto (centro)","Nara","Osaka"]'::jsonb, 0, 'O Byodo-in, com seu icônico Salão da Fênix, está localizado na cidade de Uji, próxima a Quioto.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Castelo de Kumamoto é conhecido por qual característica defensiva incomum em sua construção?', '["Muros curvos projetados para dificultar escaladas","Um fosso feito de lava vulcânica","Torres subterrâneas conectadas por túneis","Portões feitos inteiramente de ferro"]'::jsonb, 0, 'O Castelo de Kumamoto é famoso por seus muros de pedra curvos, conhecidos como ''muros que repelem ladrões'', dificultando escaladas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que é um ''pagode'' em templos budistas japoneses, como o encontrado no Todai-ji ou no Horyu-ji?', '["Uma torre de múltiplos andares com função religiosa e simbólica","Um tipo de portão de entrada","Um jardim de meditação","Uma estátua de Buda deitado"]'::jsonb, 0, 'O pagode é uma torre de vários andares, com origem indiana (stupa), usada para abrigar relíquias sagradas em templos budistas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo Horyu-ji, próximo a Nara, é reconhecido por abrigar quais das estruturas de madeira mais antigas do mundo?', '["As estruturas de madeira mais antigas do mundo ainda existentes","Apenas réplicas modernas de templos antigos","A maior escultura de Buda do Japão","O primeiro templo budista construído na China"]'::jsonb, 0, 'O Horyu-ji abriga algumas das estruturas de madeira mais antigas do mundo, datando do início do século VII.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Santuário Meiji, um dos mais visitados de Tóquio, foi construído em homenagem a qual imperador?', '["Imperador Meiji","Imperador Hirohito","Imperador Akihito","Imperador Taisho"]'::jsonb, 0, 'O Santuário Meiji foi construído em homenagem ao imperador Meiji e à imperatriz Shoken, após suas mortes no início do século XX.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O centro histórico de Kanazawa preserva um bairro tradicional de geishas conhecido como:', '["Higashi Chaya","Gion","Pontocho","Miyagawa-cho"]'::jsonb, 0, 'O bairro Higashi Chaya, em Kanazawa, preserva casas de chá tradicionais associadas à cultura das gueixas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O famoso bairro Gion, tradicionalmente associado às gueixas, está localizado em qual cidade?', '["Quioto","Tóquio","Osaka","Nagasaki"]'::jsonb, 0, 'Gion é um distrito histórico de Quioto, famoso por preservar a tradição das gueixas e das casas de chá.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Castelo de Nijo, em Quioto, é famoso por possuir pisos que rangem propositalmente. Qual era a função desse mecanismo?', '["Alertar sobre a presença de intrusos, como um sistema de segurança","Facilitar a limpeza do castelo","Reduzir o peso da estrutura","Melhorar a acústica para música tradicional"]'::jsonb, 0, 'Os famosos ''pisos de rouxinol'' (uguisubari) do Castelo de Nijo rangiam propositalmente para alertar sobre passos de possíveis intrusos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Shinkansen, o famoso trem-bala japonês, teve sua primeira linha inaugurada em qual ano, conectando Tóquio a Osaka?', '["1964","1980","1945","2000"]'::jsonb, 0, 'O primeiro Shinkansen entrou em operação em 1964, ano dos Jogos Olímpicos de Tóquio, ligando Tóquio a Osaka.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo Chuson-ji, com seu famoso ''Salão Dourado'' (Konjikido), está localizado em qual região do Japão?', '["Hiraizumi","Hokkaido","Okinawa","Shikoku"]'::jsonb, 0, 'O Chuson-ji, com seu Salão Dourado revestido de ouro, fica na cidade histórica de Hiraizumi, no nordeste do Japão.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que é um ''xogunato'', sistema de governo historicamente associado a estruturas como o Castelo de Edo (atual Palácio Imperial de Tóquio)?', '["Um governo militar liderado por um xogum, com o imperador em papel simbólico","Uma assembleia de sacerdotes budistas","Um conselho de comerciantes","Um sistema de governo eleito democraticamente"]'::jsonb, 0, 'O xogunato era um governo militar de fato, liderado por um xogum, enquanto o imperador mantinha um papel majoritariamente simbólico.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Ilha de Okunoshima, conhecida por sua grande população de coelhos selvagens, também guarda ruínas de qual tipo de instalação histórica?', '["Uma fábrica secreta de armas químicas da Segunda Guerra Mundial","Um antigo templo abandonado","Uma base naval americana","Uma colônia de pescadores do século XVIII"]'::jsonb, 0, 'Durante a Segunda Guerra Mundial, a ilha abrigou uma fábrica secreta de armas químicas do exército japonês, hoje em ruínas visitáveis.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Cidade Proibida, antigo palácio imperial chinês, está localizada em qual cidade?', '["Pequim","Xangai","Xi''an","Nanjing"]'::jsonb, 0, 'A Cidade Proibida fica no centro de Pequim e foi residência dos imperadores chineses por quase 500 anos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Por que o antigo palácio imperial chinês é chamado de ''Cidade Proibida''?', '["Porque o acesso era restrito ao imperador, sua família e servidores","Porque nunca foi visitada por estrangeiros","Porque ficava em uma área de guerra constante","Porque era construída sobre um território sagrado inacessível"]'::jsonb, 0, 'O nome vem do fato de que, por séculos, a entrada era proibida à maioria da população, sendo reservada ao imperador e sua corte.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Durante quais dinastias a Cidade Proibida serviu como residência oficial dos imperadores da China?', '["Dinastias Ming e Qing","Dinastias Han e Tang","Dinastia Song apenas","Dinastia Yuan apenas"]'::jsonb, 0, 'A Cidade Proibida foi residência imperial durante as dinastias Ming e Qing, de 1420 até 1912.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Exército de Terracota, formado por milhares de estátuas de soldados, foi descoberto próximo a qual cidade chinesa?', '["Xi''an","Pequim","Xangai","Chengdu"]'::jsonb, 0, 'O Exército de Terracota foi encontrado próximo à cidade de Xi''an, antiga capital da China.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Exército de Terracota foi construído para proteger o túmulo de qual imperador chinês?', '["Qin Shi Huang, o primeiro imperador da China unificada","Kublai Khan","O imperador Kangxi","Confúcio"]'::jsonb, 0, 'As estátuas foram enterradas para proteger o túmulo de Qin Shi Huang, fundador da dinastia Qin e primeiro imperador de uma China unificada.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Em que ano o Exército de Terracota foi descoberto por agricultores locais?', '["1974","1949","1911","2001"]'::jsonb, 0, 'O Exército de Terracota foi descoberto acidentalmente por agricultores em 1974, enquanto cavavam um poço.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Aproximadamente quantos soldados de terracota, segundo estimativas, compõem o exército enterrado próximo ao túmulo do imperador Qin?', '["Cerca de 8.000","Cerca de 500","Cerca de 100.000","Cerca de 50"]'::jsonb, 0, 'Estima-se que o exército seja composto por mais de 8.000 estátuas de soldados, além de cavalos e carruagens, cada uma com feições ligeiramente diferentes.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo do Céu, importante complexo religioso de Pequim, era usado pelos imperadores para qual finalidade?', '["Realizar cerimônias e orações por boas colheitas","Servir de residência de verão","Guardar tesouros imperiais","Sediar julgamentos oficiais"]'::jsonb, 0, 'O Templo do Céu era o local onde os imperadores realizavam cerimônias anuais de oração ao céu por boas colheitas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Palácio de Potala, importante marco arquitetônico no Tibete, foi historicamente residência de qual liderança religiosa?', '["O Dalai Lama","O imperador chinês","Um patriarca budista Zen","Um sultão mongol"]'::jsonb, 0, 'O Palácio de Potala, em Lhasa, foi a residência de inverno dos Dalai Lamas até meados do século XX.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Em que cidade está localizado o Palácio de Potala?', '["Lhasa","Xangai","Chengdu","Kunming"]'::jsonb, 0, 'O Palácio de Potala está localizado em Lhasa, capital histórica e religiosa do Tibete.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Grande Buda de Leshan, uma das maiores estátuas de Buda esculpidas em pedra do mundo, está localizado em qual província chinesa?', '["Sichuan","Guangdong","Yunnan","Hunan"]'::jsonb, 0, 'O Grande Buda de Leshan foi esculpido em um penhasco na província de Sichuan, no sudoeste da China.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Grande Buda de Leshan foi esculpido no encontro de quais rios, segundo a tradição, para acalmar as águas turbulentas?', '["Os rios Min e Dadu","Os rios Yangtzé e Amarelo","O Rio Pérola e o Rio Han","O Rio Mekong e o Rio Salween"]'::jsonb, 0, 'A estátua foi esculpida no encontro dos rios Min e Dadu, com a intenção de acalmar as águas turbulentas que causavam acidentes com barcos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Grande Muralha da China é frequentemente associada a um mito popular. Qual dessas afirmações sobre ela é verdadeira?', '["Ela não é visível a olho nu do espaço, ao contrário do que diz um mito popular","Ela é visível facilmente da Lua","Ela foi construída em menos de 10 anos","Ela tem exatamente 1.000 km de extensão"]'::jsonb, 0, 'Ao contrário de um mito popular, astronautas confirmam que a Grande Muralha não é facilmente visível a olho nu do espaço.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Jardim Humble Administrator (Jardim do Administrador Humilde), um dos mais famosos jardins clássicos chineses, fica em qual cidade?', '["Suzhou","Hangzhou","Nanjing","Guilin"]'::jsonb, 0, 'O Jardim do Administrador Humilde é um dos jardins clássicos mais famosos da China, localizado na cidade de Suzhou.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A cidade de Suzhou é frequentemente comparada a qual cidade europeia, por causa de seus canais?', '["Veneza","Amsterdã","Paris","Londres"]'::jsonb, 0, 'Suzhou é apelidada de ''Veneza do Oriente'' devido à sua rede de canais e pontes antigas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo de Shaolin, famoso por sua associação com as artes marciais chinesas, fica em qual província?', '["Henan","Sichuan","Fujian","Shandong"]'::jsonb, 0, 'O lendário Templo de Shaolin, berço do kung fu Shaolin, está localizado na província de Henan.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Os montes de Guilin, com suas formações cársticas únicas retratadas em pinturas tradicionais chinesas, ficam em qual região?', '["Guangxi","Tibete","Mongólia Interior","Xinjiang"]'::jsonb, 0, 'As formações cársticas de Guilin, na região de Guangxi, são um dos cenários naturais mais icônicos e pintados da China.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Bund, famosa avenida à beira-rio com prédios históricos de estilo ocidental, é um marco de qual cidade chinesa?', '["Xangai","Pequim","Guangzhou","Tianjin"]'::jsonb, 0, 'O Bund é uma avenida histórica à beira do rio Huangpu, em Xangai, conhecida por seus edifícios de arquitetura ocidental do início do século XX.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Torre de Porcelana de Nanjing, uma maravilha da China antiga hoje reconstruída, era originalmente revestida de quê?', '["Tijolos de porcelana branca e vidrados coloridos","Placas de ouro maciço","Mármore importado da Itália","Bambu laqueado"]'::jsonb, 0, 'A torre original era revestida com tijolos de porcelana branca e elementos vidrados coloridos, sendo considerada uma das maravilhas do mundo medieval.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Palácio de Verão, complexo de jardins e lagos usado pela família imperial chinesa, está localizado em qual cidade?', '["Pequim","Xangai","Xi''an","Chengdu"]'::jsonb, 0, 'O Palácio de Verão fica nos arredores de Pequim e era usado pela corte imperial como refúgio durante o verão.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Quem foi a imperatriz historicamente associada à reconstrução do Palácio de Verão no final do século XIX?', '["Imperatriz Viúva Cixi","Imperatriz Wu Zetian","Rainha Consorte Wanrong","Imperatriz Ma"]'::jsonb, 0, 'A Imperatriz Viúva Cixi ficou conhecida por usar recursos do tesouro naval para reconstruir e embelezar o Palácio de Verão.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Grande Muralha da China é composta principalmente de quais materiais, variando conforme a época e a região?', '["Terra socada, pedra e tijolo","Apenas mármore","Apenas ferro fundido","Bambu e madeira exclusivamente"]'::jsonb, 0, 'Dependendo da época e da região, a muralha foi construída com terra socada, pedra, tijolo e outros materiais disponíveis localmente.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo Branco de Nuvens (Baiyun Guan), importante centro do taoísmo, está localizado em qual cidade?', '["Pequim","Xangai","Chengdu","Kunming"]'::jsonb, 0, 'O Baiyun Guan é um dos templos taoístas mais importantes da China, localizado em Pequim.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A antiga Rota da Seda, importante rede de comércio histórico, conectava a China a quais outras regiões do mundo?', '["Ásia Central, Oriente Médio e Europa","Apenas o Japão e a Coreia","Somente o Sudeste Asiático","Exclusivamente a África"]'::jsonb, 0, 'A Rota da Seda era uma rede de rotas comerciais que ligava a China à Ásia Central, ao Oriente Médio e, por fim, à Europa.');
insert into tourism_questions (question, options, correct_index, explanation) values ('As Cavernas de Mogao, importante sítio budista com milhares de pinturas e esculturas, ficam próximas a qual cidade da Rota da Seda?', '["Dunhuang","Xi''an","Kashgar","Lanzhou"]'::jsonb, 0, 'As Cavernas de Mogao, com centenas de grutas decoradas com arte budista, ficam próximas à cidade de Dunhuang.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo de Confúcio, dedicado ao filósofo chinês, encontra-se principalmente em qual cidade natal dele?', '["Qufu","Pequim","Xangai","Xi''an"]'::jsonb, 0, 'O Templo de Confúcio mais importante fica em Qufu, cidade natal do filósofo, na província de Shandong.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Confúcio, homenageado em templos por toda a China, foi principalmente qual tipo de figura histórica?', '["Um filósofo e educador","Um imperador guerreiro","Um general militar","Um explorador marítimo"]'::jsonb, 0, 'Confúcio foi um filósofo, educador e pensador político chinês cujas ideias influenciaram profundamente a cultura chinesa.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Distrito de Hutong, com suas vielas tradicionais e pátios históricos, é uma característica típica de qual cidade?', '["Pequim","Xangai","Guangzhou","Shenzhen"]'::jsonb, 0, 'Os hutongs são becos e vielas tradicionais formados por antigas residências com pátio, típicos da arquitetura histórica de Pequim.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Monte Tai, uma das montanhas sagradas mais importantes da China, está associado a qual tradição filosófica/religiosa?', '["O taoísmo","O cristianismo","O islamismo","O xintoísmo (que é japonês)"]'::jsonb, 0, 'O Monte Tai é uma das cinco montanhas sagradas do taoísmo chinês, historicamente visitada por imperadores para realizar cerimônias.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Zoológico e a Torre de TV de Xangai, a Oriental Pearl Tower, são reconhecidos por qual característica arquitetônica marcante?', '["Suas esferas metálicas ao longo da estrutura","Seu formato piramidal","Sua fachada revestida de ouro","Seu formato de dragão"]'::jsonb, 0, 'A Oriental Pearl Tower é reconhecida por suas grandes esferas metálicas dispostas ao longo da torre, lembrando pérolas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Portão de Tiananmen, entrada histórica para a Cidade Proibida, dá nome a qual famosa praça de Pequim?', '["Praça Tiananmen","Praça da Paz Celestial Ocidental","Praça do Povo","Praça Vermelha (que é russa)"]'::jsonb, 0, 'O Portão de Tiananmen dá nome à Praça Tiananmen, uma das maiores praças públicas do mundo, no centro de Pequim.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que significa ''Tiananmen'' em chinês?', '["''Portão da Paz Celestial''","''Portão do Dragão Dourado''","''Portão dos Imperadores''","''Portão da Grande Muralha''"]'::jsonb, 0, '''Tiananmen'' significa aproximadamente ''Portão da Paz Celestial'', nome carregado de simbolismo na tradição imperial chinesa.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Grande Muralha teve, ao longo da história, qual outra função além da militar, relacionada ao comércio?', '["Controlar e taxar o comércio ao longo da Rota da Seda","Servir como via exclusiva para peregrinos religiosos","Funcionar como aqueduto para irrigação","Servir de estrada para caravanas de sal"]'::jsonb, 0, 'Além da defesa militar, a muralha também ajudava a controlar e taxar o comércio de caravanas que cruzavam a fronteira norte da China.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Mausoléu de Qin Shi Huang, onde está o túmulo do imperador que ordenou o Exército de Terracota, permanece até hoje em qual condição?', '["Ainda não foi totalmente escavado pelos arqueólogos","Foi completamente destruído por saqueadores","Está aberto à visitação pública em seu interior","Foi transformado em um templo budista"]'::jsonb, 0, 'O túmulo principal do imperador ainda não foi escavado, por razões técnicas e de preservação, permanecendo um mistério parcial até hoje.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo Lama (Yonghe Gong), um dos templos budistas tibetanos mais importantes fora do Tibete, está localizado em qual cidade?', '["Pequim","Lhasa","Chengdu","Xining"]'::jsonb, 0, 'O Yonghe Gong, ou Templo Lama, é um importante templo budista tibetano localizado em Pequim.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Represa das Três Gargantas, uma das maiores obras de engenharia moderna da China, foi construída sobre qual rio?', '["Rio Yangtzé","Rio Amarelo","Rio Pérola","Rio Mekong"]'::jsonb, 0, 'A Represa das Três Gargantas foi construída sobre o rio Yangtzé, o maior rio da Ásia, e é a maior usina hidrelétrica do mundo em capacidade instalada.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Antigo Observatório Astronômico de Pequim, ainda preservado, foi construído inicialmente durante qual dinastia?', '["Dinastia Yuan","Dinastia Han","Dinastia Song","Dinastia Qin"]'::jsonb, 0, 'O observatório de Pequim tem origens na dinastia Yuan, no século XIII, e foi expandido em dinastias posteriores.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Os Terraços de Arroz de Longsheng, importante paisagem cultural chinesa, ficam esculpidos em qual tipo de terreno?', '["Encostas de montanhas","Planícies costeiras","Desertos irrigados","Ilhas fluviais"]'::jsonb, 0, 'Os famosos terraços de arroz de Longsheng foram esculpidos ao longo de encostas de montanhas, técnica agrícola milenar chinesa.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Palácio Potala, no Tibete, é construído em qual tipo de terreno elevado, o que reforça seu caráter simbólico e defensivo?', '["No topo da Colina Vermelha (Marpo Ri)","No fundo de um vale fértil","Sobre uma ilha em um lago sagrado","Em uma caverna natural nas montanhas"]'::jsonb, 0, 'O Palácio de Potala foi construído no topo da Colina Vermelha (Marpo Ri), dominando a paisagem de Lhasa.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Forte Vermelho (Red Fort), importante monumento histórico indiano, está localizado em qual cidade?', '["Nova Deli","Agra","Jaipur","Mumbai"]'::jsonb, 0, 'O Forte Vermelho fica em Nova Deli e foi a principal residência dos imperadores mogóis por quase 200 anos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Forte Vermelho de Deli recebe esse nome por causa de qual característica?', '["A cor avermelhada de sua construção em arenito","Por ter sido palco de uma grande batalha sangrenta","Por abrigar uma coleção de rubis","Por ser pintado de vermelho anualmente em um festival"]'::jsonb, 0, 'O forte recebe o nome por ser construído principalmente em arenito vermelho, característico da arquitetura mogol da região.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual imperador mogol ordenou a construção do Forte Vermelho, o mesmo responsável pelo Taj Mahal?', '["Shah Jahan","Akbar","Aurangzeb","Babur"]'::jsonb, 0, 'O Forte Vermelho de Deli foi construído a mando do imperador Shah Jahan, o mesmo que construiu o Taj Mahal.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Qutub Minar, um dos minaretes de tijolo mais altos do mundo, está localizado em qual cidade?', '["Nova Deli","Agra","Varanasi","Hyderabad"]'::jsonb, 0, 'O Qutub Minar fica em Nova Deli e é um dos monumentos históricos mais importantes da Índia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Qutub Minar foi construído inicialmente para comemorar qual tipo de evento histórico?', '["O início do domínio muçulmano na região de Deli","Uma vitória militar hindu","A fundação do primeiro templo budista da Índia","A chegada dos portugueses à Índia"]'::jsonb, 0, 'A construção do Qutub Minar foi iniciada para marcar o início do domínio muçulmano na região, no final do século XII.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Hawa Mahal, conhecido como ''Palácio dos Ventos'' por suas centenas de pequenas janelas, está localizado em qual cidade?', '["Jaipur","Udaipur","Jodhpur","Bikaner"]'::jsonb, 0, 'O Hawa Mahal fica na cidade de Jaipur, conhecida como a ''Cidade Rosa'' da Índia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual era a principal função das centenas de pequenas janelas do Hawa Mahal, na tradição da corte real?', '["Permitir que as mulheres da corte observassem a rua sem serem vistas","Servir como saída de emergência em caso de incêndio","Melhorar a ventilação de um hospital","Funcionar como um sistema de sinalização militar"]'::jsonb, 0, 'As janelas permitiam que as mulheres da realeza observassem a vida na rua e celebrações, mantendo-se ocultas conforme os costumes da época.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo Dourado (Harmandir Sahib), local mais sagrado do siquismo, está localizado em qual cidade indiana?', '["Amritsar","Nova Deli","Chandigarh","Ludhiana"]'::jsonb, 0, 'O Templo Dourado fica na cidade de Amritsar, no estado de Punjab, e é o principal centro espiritual do siquismo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Por que o Harmandir Sahib é popularmente conhecido como ''Templo Dourado''?', '["Por sua cúpula e parte da fachada serem revestidas de ouro","Por ficar ao lado de minas de ouro","Por ser construído inteiramente com moedas de ouro derretidas","Por seu nome original significar ''ouro'' em punjabi"]'::jsonb, 0, 'A cúpula superior e parte da fachada do templo são revestidas com folhas de ouro, o que lhe deu o apelido popular.');
insert into tourism_questions (question, options, correct_index, explanation) values ('As Cavernas de Ajanta e Ellora, importantes sítios de arte rupestre indiana, estão localizadas em qual estado?', '["Maharashtra","Rajasthan","Kerala","Punjab"]'::jsonb, 0, 'As Cavernas de Ajanta e Ellora, esculpidas na rocha com templos e pinturas antigas, ficam no estado de Maharashtra.');
insert into tourism_questions (question, options, correct_index, explanation) values ('As Cavernas de Ellora são notáveis por reunir templos de quais tradições religiosas diferentes no mesmo complexo?', '["Budismo, hinduísmo e jainismo","Apenas hinduísmo","Apenas islamismo","Cristianismo e judaísmo"]'::jsonb, 0, 'As Cavernas de Ellora reúnem, em um mesmo complexo, templos esculpidos na rocha de três tradições: budismo, hinduísmo e jainismo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Portão da Índia (Gateway of India), importante monumento à beira-mar, está localizado em qual cidade?', '["Mumbai","Chennai","Kolkata","Goa"]'::jsonb, 0, 'O Portão da Índia fica em Mumbai, à beira do Mar Arábico, e foi construído no início do século XX.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Portão da Índia, em Mumbai, foi construído para comemorar qual evento histórico?', '["A visita do rei George V e da rainha Mary à Índia, em 1911","A independência da Índia, em 1947","A fundação da cidade de Mumbai","O fim da Segunda Guerra Mundial"]'::jsonb, 0, 'O monumento foi erguido para comemorar o desembarque do rei George V e da rainha Mary, em sua visita à Índia britânica em 1911.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo do Lótus, com sua arquitetura em forma de flor, é um templo dedicado a qual religião?', '["A Fé Bahá''í","O hinduísmo","O budismo","O jainismo"]'::jsonb, 0, 'O Templo do Lótus, em Nova Deli, é uma casa de adoração da Fé Bahá''í, aberta a pessoas de todas as religiões.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Palácio de Mysore, um dos mais visitados da Índia, está localizado em qual estado?', '["Karnataka","Kerala","Tamil Nadu","Andhra Pradesh"]'::jsonb, 0, 'O Palácio de Mysore fica na cidade de mesmo nome, no estado de Karnataka, no sul da Índia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo de Sol de Konark, esculpido em forma de uma grande carruagem, está localizado em qual estado indiano?', '["Odisha","Bihar","Bengala Ocidental","Jharkhand"]'::jsonb, 0, 'O Templo do Sol de Konark, dedicado ao deus Surya, tem a forma de uma carruagem puxada por cavalos de pedra e fica em Odisha.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo de Sol de Konark é famoso por representar uma carruagem com quantas rodas de pedra esculpidas?', '["24 rodas","4 rodas","100 rodas","12 rodas"]'::jsonb, 0, 'O templo é decorado com 24 grandes rodas de pedra esculpidas, representando uma carruagem solar.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Palácio da Água (Lake Palace), construído no meio de um lago, está localizado em qual cidade indiana?', '["Udaipur","Jaipur","Jodhpur","Jaisalmer"]'::jsonb, 0, 'O Lake Palace fica no meio do Lago Pichola, na cidade de Udaipur, conhecida como a ''Veneza do Oriente'' indiana.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo de Meenakshi, com suas torres coloridas e ricamente esculpidas (gopurams), fica em qual cidade do sul da Índia?', '["Madurai","Chennai","Bangalore","Kochi"]'::jsonb, 0, 'O Templo de Meenakshi, dedicado à deusa Parvati, fica na cidade de Madurai, no estado de Tamil Nadu.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Os ''gopurams'', torres monumentais e coloridas presentes em templos do sul da Índia, geralmente marcam qual parte da estrutura?', '["A entrada principal do templo","O local de sepultamento dos sacerdotes","A cozinha do templo","O depósito de oferendas"]'::jsonb, 0, 'Os gopurams são torres ornamentadas que marcam as entradas dos templos hindus tradicionais do sul da Índia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Forte de Amber (Amber Fort), com sua arquitetura em arenito e mármore, fica próximo a qual cidade?', '["Jaipur","Delhi","Agra","Jodhpur"]'::jsonb, 0, 'O Forte de Amber fica nos arredores de Jaipur e é conhecido por sua combinação de estilos arquitetônicos hindu e mogol.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo de Kashi Vishwanath, um dos mais sagrados do hinduísmo, dedicado ao deus Shiva, fica em qual cidade?', '["Varanasi","Nova Deli","Mumbai","Amritsar"]'::jsonb, 0, 'O templo fica na cidade sagrada de Varanasi, às margens do rio Ganges, um dos locais mais importantes de peregrinação hindu.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O rio Ganges, um dos mais sagrados para os hindus e associado a várias cidades históricas indianas, nasce em qual cordilheira?', '["O Himalaia","Os Montes Gates Ocidentais","Os Montes Vindhya","A Cordilheira dos Andes (fora da Índia)"]'::jsonb, 0, 'O rio Ganges nasce nas geleiras do Himalaia e é considerado sagrado ao longo de todo o seu curso pelos hindus.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Complexo de Fatehpur Sikri, antiga capital mogol hoje abandonada, foi construído por qual imperador?', '["Akbar","Shah Jahan","Aurangzeb","Jahangir"]'::jsonb, 0, 'Fatehpur Sikri foi construída pelo imperador Akbar no século XVI, mas foi abandonada décadas depois, principalmente por falta de água.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Por que a cidade de Fatehpur Sikri foi abandonada pouco tempo depois de construída?', '["Principalmente pela escassez de água na região","Por causa de uma invasão estrangeira","Por um grande incêndio que destruiu grande parte da cidade","Por uma epidemia que atingiu toda a população"]'::jsonb, 0, 'A cidade foi abandonada poucas décadas após sua construção, principalmente devido à escassez de suprimento de água na região.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo de Brihadeeswarar, importante templo dedicado a Shiva com uma das maiores torres de templo da Índia, fica em qual cidade?', '["Thanjavur","Chennai","Madurai","Coimbatore"]'::jsonb, 0, 'O Templo de Brihadeeswarar, construído pela dinastia Chola, está localizado na cidade de Thanjavur, no estado de Tamil Nadu.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que caracteriza a arquitetura mogol, presente em monumentos como o Taj Mahal e o Forte Vermelho?', '["Combinação de elementos persas, islâmicos e indianos","Uso exclusivo de madeira e bambu","Influência direta da arquitetura grega antiga","Ausência total de simetria nas construções"]'::jsonb, 0, 'A arquitetura mogol combina elementos de tradições persas e islâmicas com técnicas e materiais locais indianos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Jama Masjid, uma das maiores mesquitas da Índia, está localizado em qual cidade?', '["Nova Deli","Lucknow","Hyderabad","Bhopal"]'::jsonb, 0, 'A Jama Masjid, construída pelo imperador Shah Jahan, fica no centro histórico de Nova Deli.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Palácio de Vento (Hawa Mahal) e a maioria dos edifícios históricos de Jaipur compartilham qual característica de cor, dando à cidade um apelido famoso?', '["Tons de rosa/terracota, o que rendeu à cidade o apelido de ''Cidade Rosa''","Tons de azul, apelidada de ''Cidade Azul''","Tons de branco, apelidada de ''Cidade Branca''","Tons de dourado, apelidada de ''Cidade Dourada''"]'::jsonb, 0, 'Jaipur é conhecida como a ''Cidade Rosa'' por causa da cor terracota/rosada predominante em seus edifícios históricos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A cidade de Jodhpur, com muitas construções pintadas de azul em seu centro histórico, é popularmente conhecida como:', '["''Cidade Azul''","''Cidade Rosa''","''Cidade Dourada''","''Cidade de Prata''"]'::jsonb, 0, 'Jodhpur é apelidada de ''Cidade Azul'' devido à cor predominante das casas em seu centro histórico, ao redor do Forte Mehrangarh.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Forte de Mehrangarh, um dos maiores fortes da Índia, domina a paisagem de qual cidade?', '["Jodhpur","Jaipur","Udaipur","Bikaner"]'::jsonb, 0, 'O Forte de Mehrangarh fica no alto de uma colina rochosa em Jodhpur, dominando a vista da cidade.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que é um ''stupa'', estrutura budista encontrada em monumentos indianos como o Grande Stupa de Sanchi?', '["Uma construção em formato de cúpula usada para guardar relíquias sagradas","Um tipo de portão decorativo","Uma torre residencial da realeza","Um sistema de irrigação antigo"]'::jsonb, 0, 'Um stupa é uma estrutura em formato de cúpula usada tradicionalmente para abrigar relíquias budistas sagradas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Grande Stupa de Sanchi, um dos monumentos budistas mais antigos preservados da Índia, está localizado em qual estado?', '["Madhya Pradesh","Bihar","Uttar Pradesh","Rajasthan"]'::jsonb, 0, 'O Grande Stupa de Sanchi fica no estado de Madhya Pradesh e data do período do imperador Ashoka, no século III a.C.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O imperador Ashoka, associado à disseminação do budismo e a monumentos como o Stupa de Sanchi, governou qual império?', '["O Império Máurya","O Império Gupta","O Império Mogol","O Império Chola"]'::jsonb, 0, 'Ashoka foi um dos maiores imperadores do Império Máurya, conhecido por converter-se ao budismo e promover sua difusão.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo de Akshardham, um dos maiores complexos de templos hindus do mundo, está localizado em qual cidade?', '["Nova Deli","Mumbai","Ahmedabad","Surat"]'::jsonb, 0, 'O Templo Akshardham, inaugurado em 2005, é um dos maiores e mais visitados complexos religiosos hindus, localizado em Nova Deli.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que é uma ''haveli'', tipo de construção tradicional encontrada em regiões como Rajasthan, associada a famílias ricas?', '["Uma mansão ou residência tradicional ricamente decorada","Um templo hindu de grande porte","Uma fortaleza militar","Um mercado coberto"]'::jsonb, 0, 'Havelis são mansões tradicionais, muitas vezes ricamente decoradas com pinturas e esculturas, construídas por famílias comerciantes abastadas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Complexo de Khajuraho, conhecido por seus templos ricamente esculpidos, está localizado em qual estado indiano?', '["Madhya Pradesh","Uttar Pradesh","Bihar","Rajasthan"]'::jsonb, 0, 'Os templos de Khajuraho, reconhecidos pela riqueza de suas esculturas, ficam no estado de Madhya Pradesh.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Taj Mahal é frequentemente descrito como um exemplo perfeito de qual princípio arquitetônico, visível em sua fachada?', '["Simetria","Assimetria proposital","Ausência de padrões geométricos","Estilo puramente minimalista sem ornamentos"]'::jsonb, 0, 'O Taj Mahal é célebre por sua simetria quase perfeita, tanto na estrutura principal quanto nos jardins ao seu redor.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Os jardins do tipo ''charbagh'', presentes no complexo do Taj Mahal, têm origem em qual tradição paisagística?', '["Tradição persa de jardins divididos em quatro partes","Tradição chinesa de jardins zen","Tradição europeia de jardins formais franceses","Tradição indígena americana"]'::jsonb, 0, 'O charbagh é um estilo de jardim persa dividido em quatro seções por caminhos de água, adotado pelos mogóis em monumentos como o Taj Mahal.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Kremlin de Moscou, importante complexo histórico e sede do governo russo, está localizado às margens de qual rio?', '["Rio Moscou","Rio Volga","Rio Neva","Rio Don"]'::jsonb, 0, 'O Kremlin de Moscou está situado às margens do rio Moscou, no centro histórico da capital russa.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que significa a palavra ''kremlin'' em russo?', '["Fortaleza dentro de uma cidade","Palácio real","Praça central","Muralha sagrada"]'::jsonb, 0, '''Kremlin'' é um termo russo geral para ''fortaleza'' ou ''cidadela'' dentro de uma cidade; várias cidades russas têm seu próprio kremlin, mas o de Moscou é o mais famoso.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Catedral de São Basílio, com suas cúpulas coloridas em formato de bulbo, está localizada em qual praça de Moscou?', '["Praça Vermelha","Praça do Kremlin","Praça da Revolução","Praça Manezhnaya"]'::jsonb, 0, 'A Catedral de São Basílio fica na extremidade sul da Praça Vermelha, em Moscou.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Catedral de São Basílio foi mandada construir por qual governante russo, para celebrar uma vitória militar?', '["Ivan, o Terrível","Pedro, o Grande","Catarina, a Grande","Nicolau II"]'::jsonb, 0, 'A catedral foi construída a mando de Ivan, o Terrível, para celebrar a conquista de Kazan em 1552.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Palácio de Inverno, atual sede do Museu Hermitage, está localizado em qual cidade russa?', '["São Petersburgo","Moscou","Novosibirsk","Kazan"]'::jsonb, 0, 'O Palácio de Inverno, antiga residência oficial dos czares russos, fica em São Petersburgo e hoje abriga o famoso Museu Hermitage.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Museu Hermitage, um dos maiores e mais visitados museus de arte do mundo, está localizado em qual antigo edifício?', '["O Palácio de Inverno","O Kremlin de Moscou","O Palácio de Peterhof","A Catedral de Kazan"]'::jsonb, 0, 'O Hermitage ocupa o antigo Palácio de Inverno e edifícios anexos, que foram residência oficial dos czares russos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual czarina russa é frequentemente associada à fundação da coleção de arte que deu origem ao Museu Hermitage?', '["Catarina, a Grande","Ana Ivanovna","Isabel Petrovna","Alexandra Feodorovna"]'::jsonb, 0, 'Catarina, a Grande, começou a formar a coleção de arte no século XVIII, que mais tarde se tornaria o acervo do Museu Hermitage.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Palácio de Peterhof, conhecido por suas extensas fontes douradas, foi inspirado em qual palácio europeu?', '["O Palácio de Versalhes, na França","O Palácio de Buckingham, na Inglaterra","O Palácio de Schönbrunn, na Áustria","O Palácio Real de Madrid, na Espanha"]'::jsonb, 0, 'O czar Pedro, o Grande, idealizou Peterhof como uma resposta russa ao Palácio de Versalhes, após visitar a França.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual czar russo é o principal responsável pela criação do complexo de Peterhof, incluindo seus famosos jardins e fontes?', '["Pedro, o Grande","Ivan, o Terrível","Nicolau I","Alexandre III"]'::jsonb, 0, 'Pedro, o Grande, ordenou a construção de Peterhof no início do século XVIII, como uma residência de veraneio à beira do Mar Báltico.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Igreja do Salvador sobre o Sangue Derramado, com cúpulas coloridas semelhantes às de São Basílio, foi construída em qual cidade?', '["São Petersburgo","Moscou","Novgorod","Yekaterinburgo"]'::jsonb, 0, 'Essa igreja fica em São Petersburgo e foi construída no local onde o czar Alexandre II foi assassinado em 1881.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Por que a Igreja do Salvador sobre o Sangue Derramado recebeu esse nome?', '["Foi construída no local do assassinato do czar Alexandre II","Foi palco de uma grande batalha sangrenta","Homenageia soldados mortos na Primeira Guerra Mundial","Foi erguida sobre um antigo campo de batalha medieval"]'::jsonb, 0, 'O nome faz referência ao assassinato do czar Alexandre II, que ocorreu exatamente no local onde a igreja foi erguida.');
insert into tourism_questions (question, options, correct_index, explanation) values ('São Petersburgo foi fundada por qual czar, que a projetou como uma ''janela para a Europa''?', '["Pedro, o Grande","Ivan IV","Nicolau I","Alexandre I"]'::jsonb, 0, 'Pedro, o Grande, fundou São Petersburgo em 1703 com a intenção de criar uma cidade moderna voltada para a Europa Ocidental.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Teatro Bolshoi, famoso por suas produções de balé e ópera, está localizado em qual cidade?', '["Moscou","São Petersburgo","Kiev (Ucrânia, não Rússia)","Minsk (Belarus, não Rússia)"]'::jsonb, 0, 'O Teatro Bolshoi, uma das companhias de balé e ópera mais renomadas do mundo, está localizado em Moscou.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Mausoléu de Lênin, onde o corpo embalsamado do líder soviético é exibido, está localizado em qual praça?', '["Praça Vermelha, em Moscou","Praça do Palácio, em São Petersburgo","Praça da Independência, em Kiev","Praça Vitória, em Minsk"]'::jsonb, 0, 'O Mausoléu de Lênin fica na Praça Vermelha, próximo às muralhas do Kremlin de Moscou.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Torre Spasskaya, com seu famoso relógio, é uma das principais torres de qual complexo histórico russo?', '["O Kremlin de Moscou","O Palácio de Inverno","O Mosteiro de Novodevichy","A Fortaleza de Pedro e Paulo"]'::jsonb, 0, 'A Torre Spasskaya é uma das torres históricas do Kremlin de Moscou, conhecida por seu grande relógio que marca as horas do país em transmissões oficiais.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Fortaleza de Pedro e Paulo, marco histórico fundacional, está localizada em qual cidade?', '["São Petersburgo","Moscou","Vladivostok","Sochi"]'::jsonb, 0, 'A Fortaleza de Pedro e Paulo foi a primeira construção de São Petersburgo, erguida por Pedro, o Grande, em 1703.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Mosteiro de Novodevichy, importante complexo religioso histórico, está localizado em qual cidade?', '["Moscou","São Petersburgo","Novgorod","Suzdal"]'::jsonb, 0, 'O Mosteiro de Novodevichy fica em Moscou e é reconhecido pela UNESCO como Patrimônio Mundial.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Anel de Ouro (Golden Ring) é uma rota turística que reúne cidades históricas russas conhecidas principalmente por qual característica?', '["Antigas cidades com importantes igrejas e mosteiros medievais","Fábricas do período soviético","Praias e resorts à beira-mar","Modernos arranha-céus"]'::jsonb, 0, 'O Anel de Ouro reúne cidades históricas ao redor de Moscou, famosas por seus monastérios e igrejas medievais bem preservados.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A cidade histórica de Suzdal, parte do Anel de Ouro russo, é conhecida por ter uma alta concentração de quê?', '["Igrejas e mosteiros históricos","Fábricas industriais","Museus de arte moderna","Estádios esportivos"]'::jsonb, 0, 'Suzdal é famosa por preservar um grande número de igrejas e mosteiros antigos, quase sem construções modernas em seu centro histórico.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Universidade Estatal de Moscou, com seu prédio principal em estilo ''gótico stalinista'', é um exemplo de qual grupo de edifícios conhecidos como ''Sete Irmãs''?', '["Um conjunto de arranha-céus construídos na era Stalin","Sete catedrais ortodoxas históricas","Sete pontes sobre o rio Moscou","Sete estações de metrô decoradas"]'::jsonb, 0, 'As ''Sete Irmãs'' são sete arranha-céus monumentais construídos em Moscou durante o governo de Josef Stalin, incluindo o prédio principal da Universidade Estatal de Moscou.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Metrô de Moscou é famoso mundialmente por qual característica de muitas de suas estações?', '["Decoração luxuosa, com mármore, mosaicos e lustres","Serem completamente subterrâneas sem nenhuma decoração","Terem sido construídas exclusivamente no século XXI","Serem movidas por energia solar"]'::jsonb, 0, 'Muitas estações do Metrô de Moscou, construídas a partir da década de 1930, são decoradas suntuosamente com mármore, mosaicos e obras de arte.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Teatro Mariinsky, importante casa de ópera e balé, está localizado em qual cidade?', '["São Petersburgo","Moscou","Ecaterimburgo","Novosibirsk"]'::jsonb, 0, 'O Teatro Mariinsky, um dos mais importantes teatros de ópera e balé do mundo, fica em São Petersburgo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Ilha de Kizhi, reconhecida pela UNESCO, é famosa por suas construções de madeira, incluindo qual tipo de estrutura?', '["Igrejas de madeira construídas sem pregos","Palácios de gelo permanentes","Fortalezas subterrâneas","Pontes suspensas de corda"]'::jsonb, 0, 'A Ilha de Kizhi abriga um conjunto de igrejas de madeira tradicionais, construídas com técnicas antigas sem o uso de pregos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Lago Baikal, o mais profundo e um dos mais antigos lagos do mundo, está localizado em qual região da Rússia?', '["Sibéria","Extremo Oriente Russo","Região do Cáucaso","Península de Kola"]'::jsonb, 0, 'O Lago Baikal está localizado na Sibéria e é considerado o lago de água doce mais profundo e um dos mais antigos do planeta.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Catedral de Cristo Salvador, uma das maiores igrejas ortodoxas do mundo, está localizada em qual cidade?', '["Moscou","São Petersburgo","Kiev (Ucrânia, não Rússia)","Minsk (Belarus, não Rússia)"]'::jsonb, 0, 'A Catedral de Cristo Salvador, reconstruída após ser demolida na era soviética, fica em Moscou, às margens do rio Moscou.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que aconteceu com a Catedral de Cristo Salvador original durante o período soviético?', '["Foi demolida por ordem do governo soviético","Foi transformada em museu de história natural","Continuou funcionando normalmente como igreja","Foi convertida em prédio residencial"]'::jsonb, 0, 'A catedral original foi demolida em 1931 por ordem do governo soviético, sendo reconstruída apenas na década de 1990.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Torre Ostankino, importante estrutura de telecomunicações, está localizada em qual cidade e foi, por um tempo, a estrutura autônoma mais alta do mundo?', '["Moscou","São Petersburgo","Kazan","Sochi"]'::jsonb, 0, 'A Torre Ostankino, em Moscou, foi a estrutura autônoma mais alta do mundo por vários anos após sua conclusão em 1967.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Kremlin de Moscou serve, além de marco histórico, a qual função política atual?', '["Sede oficial do governo/presidência da Rússia","Sede da Igreja Ortodoxa Russa apenas","Museu exclusivamente, sem função política","Universidade estatal"]'::jsonb, 0, 'Além de complexo histórico, o Kremlin de Moscou é atualmente a sede oficial da presidência da Federação Russa.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Quantas cúpulas coloridas, aproximadamente, tem a Catedral de São Basílio, cada uma representando um santo diferente?', '["9","3","20","50"]'::jsonb, 0, 'A Catedral de São Basílio é formada por um conjunto de 9 cúpulas distintas e coloridas, cada uma associada a diferentes santos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Museu Hermitage abriga uma das maiores coleções de arte do mundo, incluindo obras de quais grandes artistas europeus?', '["Rembrandt, Da Vinci e Picasso, entre outros","Apenas artistas russos","Somente arte contemporânea","Apenas esculturas gregas antigas"]'::jsonb, 0, 'O Hermitage possui uma vasta coleção que inclui obras de mestres como Rembrandt, Leonardo da Vinci, Picasso e muitos outros.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Avenida Nevsky Prospekt, importante rua histórica e comercial, é um marco de qual cidade russa?', '["São Petersburgo","Moscou","Volgogrado","Ecaterimburgo"]'::jsonb, 0, 'A Nevsky Prospekt é a principal avenida histórica de São Petersburgo, repleta de palácios, igrejas e lojas históricas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Monumento à Mãe Pátria (The Motherland Calls), uma das estátuas mais altas do mundo, está localizado em qual cidade russa?', '["Volgogrado","Moscou","São Petersburgo","Kazan"]'::jsonb, 0, 'A estátua Mãe Pátria Chama, que homenageia a Batalha de Stalingrado, fica em Volgogrado (antiga Stalingrado).');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Monumento à Mãe Pátria, em Volgogrado, homenageia qual evento histórico da Segunda Guerra Mundial?', '["A Batalha de Stalingrado","A Batalha de Moscou","O Cerco de Leningrado","A Batalha de Kursk"]'::jsonb, 0, 'A estátua foi erguida em homenagem aos soldados soviéticos que lutaram na decisiva Batalha de Stalingrado.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Cerco de Leningrado, lembrado em monumentos na atual São Petersburgo, durou aproximadamente quanto tempo durante a Segunda Guerra Mundial?', '["Cerca de 2 anos e meio","Cerca de 3 meses","Cerca de 1 semana","Cerca de 6 anos"]'::jsonb, 0, 'O Cerco de Leningrado durou aproximadamente 872 dias, cerca de 2 anos e meio, sendo um dos episódios mais trágicos da Segunda Guerra Mundial.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Parthenon, um dos templos mais famosos da Grécia Antiga, está localizado em qual complexo histórico de Atenas?', '["A Acrópole de Atenas","A Ágora de Atenas","O Templo de Zeus Olímpico","O Cerâmico"]'::jsonb, 0, 'O Parthenon fica no alto da Acrópole de Atenas, uma colina fortificada que abriga os principais monumentos religiosos da cidade antiga.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A qual deusa grega o Parthenon é dedicado?', '["Atena","Afrodite","Hera","Deméter"]'::jsonb, 0, 'O Parthenon é dedicado a Atena Partenos, deusa padroeira da cidade de Atenas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Em que século a.C. o Parthenon foi construído, durante o auge da democracia ateniense?', '["Século V a.C.","Século X a.C.","Século II a.C.","Século VIII a.C."]'::jsonb, 0, 'O Parthenon foi construído no século V a.C., durante o governo de Péricles, período de grande prosperidade em Atenas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O sítio arqueológico de Delfos, importante centro religioso da Grécia Antiga, era famoso por abrigar qual tipo de figura?', '["Um oráculo, que fazia previsões em nome do deus Apolo","Um exército permanente de elite","A maior biblioteca do mundo antigo","O túmulo de Alexandre, o Grande"]'::jsonb, 0, 'Delfos era o lar do famoso Oráculo, sacerdotisa que, em transe, transmitia mensagens atribuídas ao deus Apolo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Oráculo de Delfos era consultado por gregos antigos com qual objetivo principal?', '["Buscar orientação e previsões sobre decisões importantes","Realizar cerimônias de casamento","Registrar nascimentos e óbitos","Negociar tratados comerciais"]'::jsonb, 0, 'Governantes e cidadãos comuns viajavam a Delfos para consultar o oráculo antes de tomar decisões importantes, de guerras a questões pessoais.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Palácio de Cnossos, na ilha de Creta, é associado a qual civilização pré-grega?', '["A civilização minoica","A civilização micênica","A civilização fenícia","A civilização etrusca"]'::jsonb, 0, 'Cnossos foi o principal centro da civilização minoica, uma das primeiras grandes civilizações da Europa, que floresceu em Creta.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O mito grego do Minotauro e do labirinto está associado a qual sítio arqueológico?', '["O Palácio de Cnossos, em Creta","A Acrópole de Atenas","O sítio de Micenas","O templo de Delfos"]'::jsonb, 0, 'A lenda do Minotauro e seu labirinto está tradicionalmente associada ao complexo palaciano de Cnossos, na ilha de Creta.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Os Mosteiros de Meteora, construídos no topo de formações rochosas, estão localizados em qual região da Grécia?', '["Tessália","Peloponeso","Macedônia","Trácia"]'::jsonb, 0, 'Os Mosteiros de Meteora ficam no alto de pilares rochosos na região da Tessália, no centro da Grécia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Por que os monges escolheram construir os Mosteiros de Meteora em locais tão elevados e de difícil acesso?', '["Buscando isolamento espiritual e proteção contra invasões","Para facilitar o comércio com outras regiões","Por exigência de um decreto imperial romano","Para se aproximar de nascentes de água potável"]'::jsonb, 0, 'A localização de difícil acesso oferecia isolamento para a vida monástica e proteção contra invasões e saques.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo de Zeus Olímpico, um dos maiores templos da Grécia Antiga, está localizado em qual cidade?', '["Atenas","Olímpia","Esparta","Corinto"]'::jsonb, 0, 'Apesar do nome remeter a Olímpia, o Templo de Zeus Olímpico (Olympieion) está localizado em Atenas, próximo à Acrópole.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O sítio arqueológico de Olímpia, berço dos Jogos Olímpicos antigos, está localizado em qual região da Grécia?', '["Peloponeso","Ática","Creta","Trácia"]'::jsonb, 0, 'Olímpia está localizada na região do Peloponeso, no sul da Grécia continental.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Com que frequência os Jogos Olímpicos da Antiguidade eram realizados em Olímpia?', '["A cada 4 anos","A cada ano","A cada 10 anos","A cada 2 anos"]'::jsonb, 0, 'Os antigos Jogos Olímpicos eram realizados a cada quatro anos, um período conhecido como ''olimpíada''.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Teatro de Epidauro, famoso por sua acústica excepcional, era originalmente dedicado a qual tipo de atividade?', '["Apresentações teatrais e cerimônias religiosas","Batalhas de gladiadores","Corridas de cavalos","Reuniões do senado"]'::jsonb, 0, 'O Teatro de Epidauro era usado principalmente para apresentações teatrais e cerimônias ligadas ao culto de Asclépio, deus da medicina.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Acrópole de Atenas, além do Parthenon, abriga outro templo dedicado a qual figura mitológica, com uma varanda sustentada por estátuas femininas?', '["O Erecteion, com suas cariátides","O Templo de Nice","O Propileu","O Odeon de Herodes Ático"]'::jsonb, 0, 'O Erecteion é famoso por sua Varanda das Cariátides, onde colunas em formato de figuras femininas sustentam a estrutura.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que são as ''cariátides'', presentes no Erecteion, na Acrópole de Atenas?', '["Colunas esculpidas em forma de figuras femininas","Estátuas de guerreiros gregos","Vasos cerimoniais de argila","Portões decorativos de bronze"]'::jsonb, 0, 'Cariátides são colunas arquitetônicas esculpidas com a forma de figuras femininas, usadas como suporte estrutural decorativo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A cidade de Micenas, importante centro da civilização micênica, é associada a qual figura da mitologia/literatura grega, personagem da Guerra de Troia?', '["O rei Agamêmnon","O herói Hércules","O rei Minos","O filósofo Sócrates"]'::jsonb, 0, 'Micenas é tradicionalmente associada ao rei Agamêmnon, líder dos gregos na Guerra de Troia segundo a Ilíada de Homero.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Portão dos Leões, uma das entradas mais famosas de sítios arqueológicos gregos, está localizado em qual cidade antiga?', '["Micenas","Esparta","Tebas","Argos"]'::jsonb, 0, 'O Portão dos Leões é a entrada monumental da antiga cidadela de Micenas, decorada com um relevo de dois leões.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Ágora de Atenas, importante espaço público da cidade antiga, era usada principalmente para quê?', '["Comércio, política e vida social","Apenas cerimônias religiosas","Exclusivamente treinamento militar","Sepultamento de líderes políticos"]'::jsonb, 0, 'A Ágora era o centro da vida pública ateniense, usada para comércio, debates políticos, filosofia e convivência social.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Torre dos Ventos, estrutura octogonal usada como uma espécie de relógio antigo, está localizada em qual cidade?', '["Atenas","Esparta","Tebas","Corinto"]'::jsonb, 0, 'A Torre dos Ventos, na Ágora Romana de Atenas, funcionava como um relógio de sol e cata-vento, além de possuir um relógio d''água interno.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo de Apolo, principal santuário de Delfos, era dedicado a qual deus, associado à profecia e às artes?', '["Apolo","Zeus","Ares","Hermes"]'::jsonb, 0, 'O templo principal de Delfos era dedicado a Apolo, deus grego associado à profecia, música e às artes.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A cidade de Esparta, rival de Atenas na Grécia Antiga, era conhecida principalmente por sua ênfase em qual aspecto da sociedade?', '["Treinamento militar rigoroso","Desenvolvimento das artes e filosofia","Comércio marítimo extensivo","Arquitetura monumental"]'::jsonb, 0, 'Esparta era famosa por sua sociedade fortemente militarizada, com ênfase no treinamento físico e disciplina desde a infância.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Farol de Alexandria, uma das Sete Maravilhas do Mundo Antigo, embora localizado no Egito, foi construído sob domínio de qual dinastia de origem grega?', '["A dinastia ptolomaica","A dinastia dos Seleucidas","A dinastia romana","A dinastia otomana"]'::jsonb, 0, 'O Farol de Alexandria foi construído durante o reinado de Ptolomeu II, da dinastia ptolomaica, de origem grega, que governou o Egito após Alexandre, o Grande.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Estádio Panathinaiko, em Atenas, é conhecido por ter sediado quais Jogos Olímpicos modernos?', '["Os primeiros Jogos Olímpicos modernos, em 1896","Os Jogos Olímpicos de 1960","Os Jogos Olímpicos de 1936","Os primeiros Jogos Paralímpicos"]'::jsonb, 0, 'O Estádio Panathinaiko, construído em mármore, sediou os primeiros Jogos Olímpicos da era moderna, em 1896.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Estádio Panathinaiko é notável por ser construído quase inteiramente em qual material?', '["Mármore","Concreto armado","Aço","Madeira"]'::jsonb, 0, 'O estádio é uma reconstrução de um estádio antigo e é famoso por ser feito quase inteiramente de mármore branco.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A ilha de Santorini, famosa por suas construções brancas e azuis, é resultado geológico de qual tipo de evento natural?', '["Uma grande erupção vulcânica na Antiguidade","Um terremoto recente","A erosão marinha ao longo de séculos","O derretimento de uma geleira"]'::jsonb, 0, 'A formação atual da ilha de Santorini é resultado de uma das maiores erupções vulcânicas da história, ocorrida há milhares de anos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo de Poseidon, no Cabo Sunion, era dedicado a qual deus grego, associado ao mar?', '["Poseidon","Zeus","Hades","Apolo"]'::jsonb, 0, 'O templo no Cabo Sunion, com vista para o mar Egeu, era dedicado a Poseidon, deus grego dos mares e terremotos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A moderna cidade de Atenas leva o nome de qual deusa da mitologia grega?', '["Atena","Afrodite","Hera","Ártemis"]'::jsonb, 0, 'Segundo o mito, a cidade recebeu o nome de Atena após a deusa vencer uma disputa com Poseidon pelo patrocínio da cidade.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Odeon de Herodes Ático, teatro ainda usado para espetáculos, está localizado na base de qual monumento em Atenas?', '["A Acrópole","A Torre dos Ventos","O Templo de Zeus Olímpico","A Ágora Romana"]'::jsonb, 0, 'O Odeon de Herodes Ático foi construído na encosta sul da Acrópole de Atenas, no século II d.C.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Rodes, ilha grega onde ficava o Colosso de Rodes, faz parte de qual grupo de ilhas gregas?', '["Dodecaneso","Cíclades","Ilhas Jônicas","Espórades"]'::jsonb, 0, 'A ilha de Rodes faz parte do grupo de ilhas conhecido como Dodecaneso, no mar Egeu.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que caracteriza a ''ordem dórica'', um dos estilos de coluna usados em templos gregos como o Parthenon?', '["Colunas robustas e sem base, com capitéis simples","Colunas finas decoradas com folhas de acanto","Colunas em espiral coloridas","Colunas totalmente lisas sem sulcos verticais"]'::jsonb, 0, 'A ordem dórica é caracterizada por colunas robustas, sem base própria, e capitéis simples, sendo um dos três principais estilos clássicos gregos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Quais são as três principais ordens arquitetônicas clássicas da Grécia Antiga, usadas em templos como o Parthenon?', '["Dórica, jônica e coríntia","Românica, gótica e barroca","Bizantina, otomana e persa","Micênica, minoica e cicládica"]'::jsonb, 0, 'As três ordens clássicas da arquitetura grega são a dórica, a jônica e a coríntia, diferenciadas principalmente pelo estilo das colunas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O mármore usado na construção do Parthenon veio principalmente de qual monte próximo a Atenas?', '["Monte Pentélico","Monte Olimpo","Monte Parnaso","Monte Taigeto"]'::jsonb, 0, 'O mármore usado na construção do Parthenon foi extraído principalmente do Monte Pentélico, próximo a Atenas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O estadista ateniense Péricles teve papel fundamental em qual aspecto da construção do Parthenon?', '["Liderou o programa de construção que incluiu o templo","Foi o escultor responsável pelas esculturas do frontão","Financiou pessoalmente toda a obra com fortuna própria","Serviu como arquiteto principal da obra"]'::jsonb, 0, 'Péricles liderou o ambicioso programa de reconstrução da Acrópole no século V a.C., que incluiu o Parthenon, embora o projeto arquitetônico tenha sido de Ictino e Calícrates.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Esfinge de Gizé, uma das estátuas mais famosas do mundo, tem corpo de qual animal e cabeça de quê?', '["Corpo de leão e cabeça humana","Corpo de touro e cabeça de falcão","Corpo de águia e cabeça de leão","Corpo de serpente e cabeça humana"]'::jsonb, 0, 'A Esfinge de Gizé tem corpo de leão e cabeça humana, sendo uma das maiores esculturas monolíticas do mundo antigo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Esfinge de Gizé é frequentemente associada, pelo rosto esculpido, a qual faraó egípcio?', '["Quéfren (Khafre)","Tutancâmon","Ramsés II","Akhenaton"]'::jsonb, 0, 'Muitos egiptólogos associam o rosto da Esfinge ao faraó Quéfren, cuja pirâmide fica próxima ao monumento.');
insert into tourism_questions (question, options, correct_index, explanation) values ('As ruínas de Grande Zimbábue, importante sítio arqueológico africano, estão localizadas em qual país atual?', '["Zimbábue","África do Sul","Moçambique","Zâmbia"]'::jsonb, 0, 'As ruínas de Grande Zimbábue ficam no país que leva o mesmo nome, no sul da África, e dão nome à nação moderna.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Grande Zimbábue foi construída, entre os séculos XI e XV, por qual tipo de civilização?', '["Uma civilização africana bantu, com uma sociedade comercial próspera","Colonizadores europeus","Comerciantes árabes exclusivamente","Uma civilização egípcia migrante"]'::jsonb, 0, 'Grande Zimbábue foi construída por povos bantu locais, que desenvolveram uma sociedade próspera baseada no comércio de ouro e marfim.');
insert into tourism_questions (question, options, correct_index, explanation) values ('As Igrejas Rupestres de Lalibela, esculpidas na rocha, estão localizadas em qual país africano?', '["Etiópia","Quênia","Sudão","Tanzânia"]'::jsonb, 0, 'As famosas igrejas de Lalibela, esculpidas inteiramente na rocha, ficam na Etiópia e datam do século XII e XIII.');
insert into tourism_questions (question, options, correct_index, explanation) values ('As igrejas de Lalibela foram construídas, segundo a tradição etíope, sob ordem de qual rei?', '["O rei Lalibela","O rei Salomão","O imperador Haile Selassie","O rei Ezana"]'::jsonb, 0, 'A tradição atribui a construção das igrejas ao rei Lalibela, que teria buscado criar uma ''Nova Jerusalém'' na Etiópia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Grande Mesquita de Djenné, considerada a maior estrutura de barro/adobe do mundo, está localizada em qual país?', '["Mali","Nigéria","Senegal","Burkina Faso"]'::jsonb, 0, 'A Grande Mesquita de Djenné, no Mali, é reconhecida como a maior construção de barro do mundo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('De que material principal é construída a Grande Mesquita de Djenné, no Mali?', '["Tijolos de barro secos ao sol (adobe)","Blocos de granito","Mármore importado","Concreto armado"]'::jsonb, 0, 'A mesquita é construída com tijolos de barro secos ao sol, técnica tradicional da arquitetura sudano-saheliana.');
insert into tourism_questions (question, options, correct_index, explanation) values ('As Pirâmides de Meroé, menos conhecidas que as do Egito mas em maior número, estão localizadas em qual país?', '["Sudão","Egito","Etiópia","Líbia"]'::jsonb, 0, 'As Pirâmides de Meroé ficam no Sudão e pertenceram ao antigo Reino de Kush, com mais de 200 pirâmides menores que as egípcias.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O antigo Reino de Kush, responsável pelas pirâmides de Meroé, ficava localizado ao sul de qual civilização, com quem manteve contato próximo?', '["O antigo Egito","O Império Romano","A Pérsia Antiga","A Babilônia"]'::jsonb, 0, 'O Reino de Kush desenvolveu-se ao sul do antigo Egito, com forte influência cultural e comercial entre as duas civilizações.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Castelo de Cape Coast, importante e triste marco histórico do comércio de pessoas escravizadas, está localizado em qual país?', '["Gana","Nigéria","Senegal","Costa do Marfim"]'::jsonb, 0, 'O Castelo de Cape Coast, em Gana, foi um dos principais entrepostos usados no comércio transatlântico de pessoas escravizadas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Ilha de Gorée, também associada à história do tráfico de pessoas escravizadas, está localizada próxima a qual capital africana?', '["Dakar, no Senegal","Acra, em Gana","Lagos, na Nigéria","Abidjan, na Costa do Marfim"]'::jsonb, 0, 'A Ilha de Gorée fica próxima a Dakar, capital do Senegal, e é um importante memorial da história do tráfico transatlântico.');
insert into tourism_questions (question, options, correct_index, explanation) values ('As Pirâmides de Gizé, incluindo a Grande Pirâmide, estão localizadas em qual continente?', '["África","Ásia","Europa","América do Sul"]'::jsonb, 0, 'O Egito, onde ficam as pirâmides de Gizé, está localizado no continente africano (a parte principal do país).');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo de Abu Simbel, com suas grandes estátuas esculpidas na rocha, foi construído para qual faraó egípcio?', '["Ramsés II","Tutancâmon","Quéops","Akhenaton"]'::jsonb, 0, 'O Templo de Abu Simbel foi construído para homenagear o faraó Ramsés II, com quatro grandes estátuas suas na fachada.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que houve de excepcional na história recente do Templo de Abu Simbel, no século XX?', '["Foi transladado para um local mais alto, para não ser inundado por uma represa","Foi descoberto pela primeira vez em 1968","Foi reconstruído do zero após ser destruído por um terremoto","Foi movido para um museu na Europa"]'::jsonb, 0, 'Na década de 1960, o templo foi cuidadosamente desmontado e remontado em local mais elevado, para escapar da inundação causada pela Represa de Assuã.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Vale dos Reis, importante necrópole onde vários faraós egípcios foram sepultados, incluindo Tutancâmon, está localizado próximo a qual cidade?', '["Luxor","Cairo","Alexandria","Assuã"]'::jsonb, 0, 'O Vale dos Reis fica na margem oeste do rio Nilo, próximo à cidade de Luxor, no Egito.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Os Templos de Karnak, um dos maiores complexos religiosos do mundo antigo, estão localizados em qual cidade egípcia?', '["Luxor","Cairo","Alexandria","Assuã"]'::jsonb, 0, 'O complexo de Karnak, dedicado principalmente ao deus Amon, fica na cidade de Luxor, no Egito.');
insert into tourism_questions (question, options, correct_index, explanation) values ('As Ilhas de Robben, que abrigaram uma prisão histórica, ficam próximas a qual cidade sul-africana?', '["Cidade do Cabo","Joanesburgo","Durban","Pretória"]'::jsonb, 0, 'A Ilha Robben, onde Nelson Mandela ficou preso por anos, fica próxima à Cidade do Cabo, na África do Sul.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Ilha Robben é hoje reconhecida mundialmente por ter sido prisão de qual importante líder político?', '["Nelson Mandela","Kwame Nkrumah","Jomo Kenyatta","Julius Nyerere"]'::jsonb, 0, 'Nelson Mandela ficou preso na Ilha Robben por 18 dos 27 anos que passou encarcerado, antes de se tornar presidente da África do Sul.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Monte Kilimanjaro, ponto mais alto da África, está localizado em qual país?', '["Tanzânia","Quênia","Uganda","Ruanda"]'::jsonb, 0, 'O Monte Kilimanjaro, um vulcão inativo, está localizado na Tanzânia e é o ponto mais alto do continente africano.');
insert into tourism_questions (question, options, correct_index, explanation) values ('As Cataratas Vitória, uma das maiores quedas d''água do mundo, ficam na fronteira entre quais dois países africanos?', '["Zâmbia e Zimbábue","Quênia e Tanzânia","África do Sul e Namíbia","Egito e Sudão"]'::jsonb, 0, 'As Cataratas Vitória, no rio Zambeze, ficam na fronteira entre a Zâmbia e o Zimbábue.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O nome local das Cataratas Vitória, que significa ''a fumaça que troveja'', é:', '["Mosi-oa-Tunya","Zambezi Falls","Kariba Roar","Nyasa Thunder"]'::jsonb, 0, 'O nome tradicional das cataratas na língua local é Mosi-oa-Tunya, que significa ''a fumaça que troveja''.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A antiga cidade de Cartago, importante centro comercial da Antiguidade, ficava localizada no que hoje é qual país?', '["Tunísia","Argélia","Marrocos","Líbia"]'::jsonb, 0, 'Cartago, rival histórica de Roma, ficava próxima à atual cidade de Túnis, capital da Tunísia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A cidade de Cartago foi, segundo a tradição, fundada por qual povo antigo do Mediterrâneo?', '["Os fenícios","Os gregos","Os romanos","Os persas"]'::jsonb, 0, 'Cartago foi fundada por colonizadores fenícios, vindos da região da atual Líbano, por volta do século IX a.C.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Medina de Fez, um dos maiores centros urbanos históricos preservados do mundo, está localizada em qual país?', '["Marrocos","Argélia","Tunísia","Egito"]'::jsonb, 0, 'A Medina de Fez, com sua intrincada rede de ruelas medievais, fica no Marrocos e é Patrimônio Mundial da UNESCO.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que caracteriza uma ''medina'', termo usado para os centros históricos de várias cidades do Norte da África?', '["A parte antiga e murada de uma cidade, com ruas estreitas","Um tipo de mesquita específica","Um mercado exclusivamente ao ar livre","Um palácio real fortificado"]'::jsonb, 0, 'Uma medina é o bairro histórico e geralmente murado de cidades no Norte da África e Oriente Médio, marcado por ruas estreitas e sinuosas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo de Filae, dedicado à deusa Ísis, também foi transladado para escapar da inundação de uma represa egípcia. Isso ocorreu em qual rio?', '["Rio Nilo","Rio Congo","Rio Níger","Rio Zambeze"]'::jsonb, 0, 'Assim como Abu Simbel, o Templo de Filae foi transladado para uma ilha próxima para escapar das águas represadas do rio Nilo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A civilização do Antigo Egito se desenvolveu principalmente ao longo de qual rio?', '["Rio Nilo","Rio Congo","Rio Níger","Rio Volta"]'::jsonb, 0, 'O Antigo Egito floresceu ao longo do rio Nilo, cujas cheias anuais fertilizavam as terras usadas para agricultura.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Deserto do Saara, onde estão localizadas várias rotas históricas de caravanas comerciais, é o maior deserto de qual tipo no mundo?', '["O maior deserto quente do mundo","O maior deserto frio do mundo","O único deserto da África","O menor deserto do continente africano"]'::jsonb, 0, 'O Saara é o maior deserto quente do mundo, tendo sido historicamente cruzado por importantes rotas de caravanas comerciais.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A cidade histórica de Timbuktu, importante centro de comércio e conhecimento islâmico medieval, está localizada em qual país?', '["Mali","Níger","Chade","Mauritânia"]'::jsonb, 0, 'Timbuktu, no Mali, foi um dos mais importantes centros de comércio, cultura e ensino islâmico durante a Idade Média.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Timbuktu era famosa, na Idade Média, por abrigar um grande número de quê, atraindo estudiosos de várias regiões?', '["Manuscritos antigos e bibliotecas islâmicas","Templos budistas","Catedrais católicas","Fábricas de tecelagem"]'::jsonb, 0, 'A cidade abrigava importantes bibliotecas com milhares de manuscritos antigos sobre ciência, religião e direito islâmico.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Complexo Funerário de Djoser, que abriga a Pirâmide de Degraus, é considerado o precursor de qual tipo de construção egípcia?', '["As pirâmides egípcias posteriores, como a de Gizé","Os templos gregos","As catedrais medievais","Os zigurates da Mesopotâmia"]'::jsonb, 0, 'A Pirâmide de Degraus de Djoser, em Saqqara, é considerada a precursora das pirâmides egípcias de faces lisas construídas posteriormente, como as de Gizé.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Quem foi o arquiteto egípcio tradicionalmente associado ao projeto da Pirâmide de Degraus de Djoser?', '["Imhotep","Hemiunu","Senemut","Ineni"]'::jsonb, 0, 'Imhotep, importante figura da história egípcia, é tradicionalmente creditado como o arquiteto responsável pela Pirâmide de Degraus.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Grande Esfinge de Gizé é esculpida principalmente a partir de qual tipo de rocha natural?', '["Um afloramento de calcário natural","Blocos de granito transportados","Mármore importado","Arenito vermelho"]'::jsonb, 0, 'A Esfinge foi esculpida diretamente de um grande afloramento de calcário natural presente no platô de Gizé.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Torre Eiffel, símbolo de Paris, foi construída para qual evento internacional?', '["A Exposição Universal de 1889","As Olimpíadas de 1900","O centenário da Revolução Francesa isoladamente, sem exposição","A coroação de Napoleão III"]'::jsonb, 0, 'A Torre Eiffel foi construída como o arco de entrada para a Exposição Universal de 1889, que também celebrava o centenário da Revolução Francesa.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Quem foi o engenheiro que dá nome à Torre Eiffel, responsável pela empresa que a projetou e construiu?', '["Gustave Eiffel","Auguste Perret","Le Corbusier","Georges-Eugène Haussmann"]'::jsonb, 0, 'A torre leva o nome do engenheiro Gustave Eiffel, cuja empresa venceu o concurso para o projeto.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Originalmente, a Torre Eiffel foi muito criticada por artistas e intelectuais parisienses. O que estava planejado para ela após 20 anos?', '["Ser desmontada","Ser pintada de dourado","Ser transformada em museu de arte","Ser vendida para outro país"]'::jsonb, 0, 'A torre tinha permissão temporária e estava planejada para ser desmontada 20 anos após sua construção, mas foi mantida por sua utilidade em telecomunicações.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Coliseu de Roma e outros monumentos históricos da cidade estão localizados em qual país europeu?', '["Itália","Espanha","Grécia","Portugal"]'::jsonb, 0, 'Roma, com o Coliseu e diversos outros monumentos antigos, é a capital da Itália.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Torre de Pisa, famosa por sua inclinação, está localizada em qual cidade italiana?', '["Pisa","Florença","Veneza","Milão"]'::jsonb, 0, 'A Torre de Pisa, oficialmente o campanário da catedral local, fica na cidade de Pisa, na região da Toscana.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que causou a famosa inclinação da Torre de Pisa?', '["Um solo instável e desigual sob a fundação","Um terremoto histórico","Um erro proposital do arquiteto para criar um efeito visual","Bombardeios durante uma guerra"]'::jsonb, 0, 'A inclinação começou já durante a construção, causada por um solo macio e desigual que não sustentava adequadamente a fundação.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A cidade de Veneza, conhecida por seus canais, está construída sobre uma série de quê?', '["Pequenas ilhas em uma lagoa","Uma única grande rocha","Um antigo vulcão extinto","Colunas de concreto no oceano aberto"]'::jsonb, 0, 'Veneza foi construída sobre um arquipélago de pequenas ilhas dentro de uma lagoa, conectadas por canais e pontes.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Sagrada Família, famosa igreja ainda em construção, está localizada em qual cidade espanhola?', '["Barcelona","Madri","Sevilha","Valência"]'::jsonb, 0, 'A Sagrada Família fica em Barcelona e é uma das obras mais famosas do arquiteto Antoni Gaudí.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Quem foi o arquiteto responsável pelo projeto original da Sagrada Família?', '["Antoni Gaudí","Rafael Moneo","Santiago Calatrava","Frank Gehry"]'::jsonb, 0, 'A Sagrada Família é a obra-prima inacabada do arquiteto catalão Antoni Gaudí, que dedicou décadas ao projeto.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Por que a construção da Sagrada Família, iniciada em 1882, ainda não foi concluída até hoje?', '["É financiada apenas por doações privadas e ingressos, sem prazo fixo definido originalmente","Foi abandonada por décadas e retomada recentemente","Está proibida de ser concluída por lei","Falta o projeto arquitetônico completo, que se perdeu"]'::jsonb, 0, 'A construção sempre dependeu principalmente de doações privadas e, mais recentemente, da venda de ingressos, o que tornou o processo extremamente longo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Big Ben, famoso relógio associado ao Parlamento britânico, está localizado em qual cidade?', '["Londres","Manchester","Edimburgo","Liverpool"]'::jsonb, 0, 'O Big Ben fica junto ao Palácio de Westminster, sede do Parlamento britânico, em Londres.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Tecnicamente, o nome ''Big Ben'' se refere a quê, e não à torre inteira, como muitos acreditam?', '["Ao grande sino dentro da torre","Ao relógio como um todo","Ao arquiteto que projetou a torre","À bandeira no topo da torre"]'::jsonb, 0, 'Originalmente, ''Big Ben'' é o apelido do grande sino dentro da torre, embora popularmente o nome seja usado para toda a estrutura.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Stonehenge, o famoso monumento pré-histórico de grandes pedras, está localizado em qual país?', '["Inglaterra","Irlanda","Escócia","País de Gales"]'::jsonb, 0, 'Stonehenge está localizado na planície de Salisbury, no sul da Inglaterra.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual é a principal característica de Stonehenge que intriga arqueólogos até hoje?', '["Como grandes pedras foram transportadas e erguidas há milhares de anos","Sua localização subterrânea","O fato de ter sido construído em apenas um dia","Ser feito inteiramente de metal"]'::jsonb, 0, 'Os métodos usados para transportar e erguer as enormes pedras, algumas vindas de dezenas de quilômetros de distância, ainda intrigam pesquisadores.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Coliseu de Roma foi construído principalmente com qual material de construção?', '["Concreto e pedra travertino","Mármore maciço","Tijolos de barro cru","Madeira reforçada com ferro"]'::jsonb, 0, 'O Coliseu foi construído principalmente com concreto romano e blocos de pedra travertino, técnica avançada para a época.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Fontana di Trevi, famosa fonte onde turistas jogam moedas, está localizada em qual cidade?', '["Roma","Florença","Nápoles","Milão"]'::jsonb, 0, 'A Fontana di Trevi é uma das fontes mais famosas do mundo, localizada no centro de Roma.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Segundo a tradição popular, o que acontece quando alguém joga uma moeda na Fontana di Trevi, de costas?', '["A pessoa garante que um dia voltará a Roma","A pessoa terá sorte no amor pelo resto da vida","A pessoa se tornará rica","A pessoa terá boa saúde por um ano"]'::jsonb, 0, 'A tradição diz que jogar uma moeda de costas na fonte garante que a pessoa retornará a Roma no futuro.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Museu do Louvre, um dos maiores museus de arte do mundo, está localizado em qual cidade?', '["Paris","Londres","Roma","Madri"]'::jsonb, 0, 'O Louvre, que abriga obras como a Mona Lisa, está localizado no centro de Paris, na França.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A pirâmide de vidro na entrada do Museu do Louvre foi projetada por qual arquiteto?', '["I. M. Pei","Le Corbusier","Jean Nouvel","Renzo Piano"]'::jsonb, 0, 'A famosa pirâmide de vidro do Louvre foi projetada pelo arquiteto sino-americano I. M. Pei, inaugurada em 1989.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Acrópole à parte, a Catedral de Notre-Dame, importante marco gótico, está localizada em qual cidade?', '["Paris","Reims","Chartres","Estrasburgo"]'::jsonb, 0, 'A Catedral de Notre-Dame, um dos exemplos mais famosos da arquitetura gótica, fica no centro histórico de Paris, na Ilha da Cité.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Em 2019, a Catedral de Notre-Dame de Paris sofreu qual grave incidente, que danificou parte de sua estrutura?', '["Um grande incêndio","Um terremoto","Uma inundação do rio Sena","Um ataque de vandalismo com explosivos"]'::jsonb, 0, 'Em abril de 2019, um grande incêndio destruiu boa parte do telhado e a torre central (flèche) da catedral, que passou por extenso trabalho de restauração.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Coliseu de Verona, um dos anfiteatros romanos mais bem preservados, ainda é usado atualmente para qual finalidade?', '["Espetáculos de ópera ao ar livre","Corridas de cavalos","Sede de tribunais","Estádio de futebol"]'::jsonb, 0, 'A Arena de Verona é famosa por sediar até hoje grandes produções de ópera ao ar livre durante os meses de verão.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Castelo de Neuschwanstein, que inspirou castelos de contos de fadas modernos, está localizado em qual país?', '["Alemanha","Áustria","Suíça","França"]'::jsonb, 0, 'O Castelo de Neuschwanstein fica na Baviera, sul da Alemanha, e foi construído no século XIX por ordem do rei Ludwig II.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Castelo de Neuschwanstein é famoso por ter servido de inspiração para qual castelo de um parque temático famoso?', '["O Castelo da Cinderela, da Disney","O Castelo de Hogwarts, de Harry Potter","O castelo do filme Shrek","O castelo de Frozen"]'::jsonb, 0, 'Neuschwanstein é frequentemente citado como uma das principais inspirações para o Castelo da Cinderela, ícone dos parques da Disney.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Portão de Brandemburgo, importante símbolo histórico alemão, está localizado em qual cidade?', '["Berlim","Munique","Frankfurt","Hamburgo"]'::jsonb, 0, 'O Portão de Brandemburgo, antigo marco da divisão entre Berlim Oriental e Ocidental, fica no centro de Berlim.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Portão de Brandemburgo se tornou um símbolo de qual evento histórico importante, ocorrido em 1989?', '["A queda do Muro de Berlim","A reunificação da Alemanha Nazista","O início da Guerra Fria","A fundação da União Europeia"]'::jsonb, 0, 'O portão tornou-se um símbolo da queda do Muro de Berlim em 1989 e, posteriormente, da reunificação alemã.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Vaticano, menor Estado soberano do mundo, abriga qual famosa basílica?', '["A Basílica de São Pedro","A Basílica de Notre-Dame","A Basílica de São Marcos","A Basílica de Santa Sofia"]'::jsonb, 0, 'A Basílica de São Pedro, uma das maiores igrejas do mundo, é o principal templo do Vaticano.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Quem foi o principal arquiteto responsável pela icônica cúpula da Basílica de São Pedro, no Vaticano?', '["Michelangelo","Bramante","Bernini","Rafael"]'::jsonb, 0, 'Michelangelo assumiu o projeto da cúpula da Basílica de São Pedro, embora ela só tenha sido concluída após sua morte.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Capela Sistina, com afrescos de Michelangelo, incluindo ''A Criação de Adão'', está localizada em qual complexo?', '["O Vaticano","O Louvre","A Torre de Londres","O Palácio de Versalhes"]'::jsonb, 0, 'A Capela Sistina fica dentro dos Museus do Vaticano, decorada com afrescos de Michelangelo no teto e em outras paredes.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Palácio de Versalhes, símbolo do poder da monarquia francesa, foi expandido principalmente por qual rei?', '["Luís XIV","Luís XVI","Napoleão Bonaparte","Henrique IV"]'::jsonb, 0, 'O Palácio de Versalhes foi expandido e transformado na grandiosa residência real por Luís XIV, o ''Rei Sol''.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O famoso Salão dos Espelhos, no Palácio de Versalhes, é conhecido historicamente por ter sediado qual evento após a Primeira Guerra Mundial?', '["A assinatura do Tratado de Versalhes","A coroação de Napoleão","A Revolução Francesa","A abdicação de Luís XVI"]'::jsonb, 0, 'O Tratado de Versalhes, que oficializou o fim da Primeira Guerra Mundial, foi assinado no Salão dos Espelhos em 1919.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Torre de Londres, antiga fortaleza real, é hoje conhecida por abrigar qual importante coleção?', '["As Joias da Coroa britânica","A maior coleção de arte moderna do Reino Unido","Documentos históricos do Parlamento","Uma coleção de armaduras medievais exclusivamente"]'::jsonb, 0, 'A Torre de Londres abriga as Joias da Coroa britânica, além de ter servido historicamente como prisão e fortaleza real.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Palácio de Buckingham, residência oficial da monarquia britânica, está localizado em qual cidade?', '["Londres","Edimburgo","Windsor","Liverpool"]'::jsonb, 0, 'O Palácio de Buckingham, residência oficial dos monarcas britânicos, fica em Londres.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A cerimônia da Troca da Guarda, tradição turística famosa, ocorre em qual monumento britânico?', '["O Palácio de Buckingham","A Torre de Londres","O Big Ben","A Abadia de Westminster"]'::jsonb, 0, 'A tradicional cerimônia de Troca da Guarda ocorre nos portões do Palácio de Buckingham.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Abadia de Westminster, importante igreja histórica britânica, é tradicionalmente usada para qual tipo de cerimônia real?', '["Coroações e casamentos reais","Apenas funerais de plebeus","Reuniões do gabinete","Sessões do tribunal supremo"]'::jsonb, 0, 'A Abadia de Westminster é tradicionalmente o local de coroações reais britânicas e de importantes casamentos e funerais da família real.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Muro de Berlim, que dividiu a cidade durante a Guerra Fria, foi derrubado em qual ano?', '["1989","1991","1961","2000"]'::jsonb, 0, 'O Muro de Berlim, erguido em 1961, foi derrubado em novembro de 1989, marcando o fim da divisão da cidade.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Castelo de Praga, um dos maiores complexos de castelo do mundo, está localizado em qual país?', '["República Tcheca","Áustria","Polônia","Eslováquia"]'::jsonb, 0, 'O Castelo de Praga, na República Tcheca, é considerado um dos maiores complexos castelares antigos do mundo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Ponte Carlos, famosa ponte histórica decorada com estátuas, está localizada em qual cidade?', '["Praga","Viena","Budapeste","Varsóvia"]'::jsonb, 0, 'A Ponte Carlos atravessa o rio Vltava em Praga e é decorada com uma série de estátuas de santos católicos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Coliseu de Roma foi usado durante séculos, após deixar de sediar espetáculos, para diferentes fins. Qual destes é verdadeiro?', '["Serviu como pedreira, com pedras retiradas para outras construções","Foi transformado em uma catedral por 500 anos","Foi usado como palácio real bizantino","Serviu de sede do governo romano medieval"]'::jsonb, 0, 'Durante a Idade Média e o Renascimento, muitas pedras do Coliseu foram retiradas e reaproveitadas na construção de outros edifícios romanos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Basílica de Santa Sofia, importante monumento histórico que já foi igreja, mesquita e museu, está localizada em qual cidade?', '["Istambul","Atenas","Roma","Moscou"]'::jsonb, 0, 'A Santa Sofia, em Istambul (Turquia), teve usos variados ao longo da história, refletindo as mudanças políticas e religiosas da região.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Basílica de Santa Sofia foi originalmente construída durante qual império?', '["O Império Bizantino","O Império Romano Ocidental","O Império Otomano, desde o início","O Império Persa"]'::jsonb, 0, 'A Santa Sofia foi construída no século VI, durante o Império Bizantino, sob o imperador Justiniano I.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Coliseu, o Big Ben e a Torre Eiffel têm em comum o fato de estarem localizados em qual continente?', '["Europa","Ásia","África","América do Sul"]'::jsonb, 0, 'Itália, Reino Unido e França estão localizados no continente europeu.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Alhambra, complexo de palácios mouriscos, está localizada em qual cidade espanhola?', '["Granada","Sevilha","Córdoba","Toledo"]'::jsonb, 0, 'A Alhambra, um dos exemplos mais notáveis da arquitetura islâmica na Europa, fica em Granada, na Espanha.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Alhambra foi construída principalmente durante qual período histórico da Espanha?', '["O período de domínio muçulmano (mouro) na Península Ibérica","O período romano","A era da Inquisição Espanhola","O reinado de Carlos V isoladamente"]'::jsonb, 0, 'A maior parte da Alhambra foi construída durante o período de domínio mouro, principalmente sob a dinastia Nasrida, entre os séculos XIII e XV.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Mesquita-Catedral de Córdoba é um exemplo notável de qual tipo de transformação arquitetônica ao longo da história?', '["Uma mesquita que foi transformada em catedral católica","Uma catedral que virou mesquita e depois voltou a ser catedral","Um templo romano transformado em sinagoga","Um castelo transformado em universidade"]'::jsonb, 0, 'A estrutura foi originalmente construída como mesquita no período mouro e, após a reconquista cristã, uma catedral foi erguida em seu interior.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Vale do Reno, na Alemanha, é famoso por reunir uma grande quantidade de qual tipo de construção medieval, ao longo do rio?', '["Castelos medievais","Catedrais góticas exclusivamente","Moinhos de vento","Fortalezas romanas"]'::jsonb, 0, 'O trecho do Vale do Reno entre Coblença e Bingen é famoso por abrigar dezenas de castelos medievais ao longo das margens do rio.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Torre de Belém, importante monumento histórico português, está localizada em qual cidade?', '["Lisboa","Porto","Coimbra","Faro"]'::jsonb, 0, 'A Torre de Belém, construída no início do século XVI, fica às margens do rio Tejo, em Lisboa.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Torre de Belém foi construída durante qual período de grande expansão marítima portuguesa?', '["A Era dos Descobrimentos","A Revolução Industrial","O período romano na Ibéria","A Reconquista cristã"]'::jsonb, 0, 'A torre foi erguida durante a Era dos Descobrimentos, período de grande expansão marítima e comercial de Portugal.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Mosteiro dos Jerónimos, em Lisboa, foi construído com recursos obtidos principalmente de qual atividade comercial?', '["O comércio de especiarias vindas do Oriente","A mineração de ouro no Brasil","O comércio de lã com a Inglaterra","A pesca do bacalhau"]'::jsonb, 0, 'O Mosteiro dos Jerónimos foi financiado principalmente pelos lucros do lucrativo comércio de especiarias trazidas do Oriente pelas navegações portuguesas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Praça Vermelha, um dos espaços públicos mais famosos do mundo, está localizada em qual cidade?', '["Moscou","São Petersburgo","Kiev (Ucrânia)","Varsóvia"]'::jsonb, 0, 'A Praça Vermelha, cercada pelo Kremlin e pela Catedral de São Basílio, fica no centro de Moscou.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Estreito de Bósforo, importante via marítima, atravessa qual cidade que liga simbolicamente a Europa e a Ásia?', '["Istambul","Atenas","Alexandria","Odessa"]'::jsonb, 0, 'Istambul é dividida pelo Estreito de Bósforo, sendo uma das poucas cidades do mundo situadas em dois continentes: Europa e Ásia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Palácio de Topkapi, antiga residência dos sultões otomanos, está localizado em qual cidade?', '["Istambul","Ancara","Izmir","Bursa"]'::jsonb, 0, 'O Palácio de Topkapi foi a principal residência dos sultões do Império Otomano por quase 400 anos, em Istambul.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Capela do Rosário e a região histórica de Cappadocia, com suas formações rochosas e igrejas subterrâneas, está localizada em qual país?', '["Turquia","Grécia","Armênia","Geórgia"]'::jsonb, 0, 'A região da Capadócia, com suas formações rochosas únicas e cidades subterrâneas históricas, fica na Turquia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('As ''cidades subterrâneas'' da região da Capadócia, na Turquia, foram originalmente escavadas com qual propósito principal?', '["Servir de abrigo e proteção contra invasores","Servir de tumbas reais","Armazenar grãos exclusivamente","Funcionar como minas de sal"]'::jsonb, 0, 'As cidades subterrâneas da Capadócia foram escavadas principalmente para servir de abrigo seguro contra invasões ao longo da história.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Coliseu, a Torre Eiffel e a Sagrada Família têm em comum o fato de serem, cada um em seu país, monumentos que atraem qual tipo de grande fluxo anual?', '["Milhões de turistas por ano","Apenas peregrinos religiosos","Somente estudantes de arquitetura","Exclusivamente delegações diplomáticas"]'::jsonb, 0, 'Esses três monumentos estão entre os pontos turísticos mais visitados do mundo, recebendo milhões de visitantes anualmente.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Monte Saint-Michel, ilha-abadia cercada por marés, está localizado em qual país?', '["França","Reino Unido","Irlanda","Bélgica"]'::jsonb, 0, 'O Mont Saint-Michel é uma ilha-comuna na costa da Normandia, na França, famosa por sua abadia medieval e marés extremas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que torna o Monte Saint-Michel um fenômeno natural notável, além de seu valor histórico?', '["As marés na região estão entre as mais fortes da Europa","Fica no topo de um vulcão ativo","É a única ilha flutuante do mundo","Muda de tamanho de acordo com as estações"]'::jsonb, 0, 'A região do Monte Saint-Michel tem uma das maiores amplitudes de maré da Europa, o que historicamente isolava a ilha em determinados horários.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Catedral de Colônia, um dos maiores exemplos de arquitetura gótica do mundo, está localizada em qual país?', '["Alemanha","Bélgica","Holanda","Suíça"]'::jsonb, 0, 'A Catedral de Colônia, com suas torres imponentes, é um dos marcos góticos mais importantes da Alemanha.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Quanto tempo, aproximadamente, levou para concluir a construção da Catedral de Colônia, incluindo interrupções ao longo dos séculos?', '["Mais de 600 anos","Cerca de 10 anos","Cerca de 50 anos","Menos de 5 anos"]'::jsonb, 0, 'Iniciada em 1248, a construção da catedral foi interrompida por séculos e só foi finalmente concluída em 1880.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Estátua da Liberdade, presente dos franceses aos Estados Unidos, está localizada em qual cidade?', '["Nova York","Washington D.C.","Boston","Filadélfia"]'::jsonb, 0, 'A Estátua da Liberdade fica na Ilha da Liberdade, na baía de Nova York.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Estátua da Liberdade foi um presente de qual país aos Estados Unidos?', '["França","Reino Unido","Espanha","Holanda"]'::jsonb, 0, 'A estátua foi um presente do povo francês aos Estados Unidos, em comemoração à amizade entre os dois países, inaugurada em 1886.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Quem foi o escultor francês responsável pela criação da Estátua da Liberdade?', '["Frédéric Auguste Bartholdi","Auguste Rodin","Gustave Eiffel (apenas a estrutura interna)","Claude Monet"]'::jsonb, 0, 'A estátua foi esculpida por Frédéric Auguste Bartholdi, enquanto Gustave Eiffel projetou a estrutura interna de suporte.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Monte Rushmore, com os rostos esculpidos de quatro presidentes americanos, está localizado em qual estado?', '["Dakota do Sul","Wyoming","Montana","Colorado"]'::jsonb, 0, 'O Monte Rushmore está localizado no estado de Dakota do Sul, nos Estados Unidos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Quais quatro presidentes dos Estados Unidos estão esculpidos no Monte Rushmore?', '["Washington, Jefferson, Roosevelt e Lincoln","Adams, Madison, Monroe e Jackson","Kennedy, Reagan, Obama e Trump","Franklin, Hamilton, Grant e Wilson"]'::jsonb, 0, 'O monumento retrata os presidentes George Washington, Thomas Jefferson, Theodore Roosevelt e Abraham Lincoln.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Ponte Golden Gate, um dos marcos mais reconhecíveis dos Estados Unidos, está localizada em qual cidade?', '["São Francisco","Los Angeles","Seattle","Portland"]'::jsonb, 0, 'A Golden Gate Bridge cruza o estreito de mesmo nome na entrada da baía de São Francisco.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual é a cor característica da Ponte Golden Gate, escolhida especificamente para se destacar na neblina da região?', '["Laranja internacional","Vermelho vivo","Azul marinho","Amarelo dourado"]'::jsonb, 0, 'A ponte é pintada na cor ''laranja internacional'', escolhida por se destacar tanto na neblina comum da região quanto contra o céu e o mar.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Casa Branca, residência oficial do presidente dos Estados Unidos, está localizada em qual cidade?', '["Washington D.C.","Nova York","Boston","Chicago"]'::jsonb, 0, 'A Casa Branca fica em Washington D.C., capital dos Estados Unidos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Chichén Itzá e outros importantes sítios maias estão localizados principalmente em qual país, além de partes da Guatemala e Belize?', '["México","Colômbia","Peru","Equador"]'::jsonb, 0, 'Grande parte dos sítios da antiga civilização maia, incluindo Chichén Itzá, está localizada no México, especialmente na península de Yucatán.');
insert into tourism_questions (question, options, correct_index, explanation) values ('As Linhas de Nazca, enormes geoglifos visíveis do alto, estão localizadas em qual país?', '["Peru","Bolívia","Chile","Equador"]'::jsonb, 0, 'As Linhas de Nazca são gigantescos desenhos traçados no solo do deserto, localizados no Peru.');
insert into tourism_questions (question, options, correct_index, explanation) values ('As Linhas de Nazca representam, entre outras figuras, quais tipos de imagens?', '["Animais, plantas e formas geométricas","Apenas rostos humanos","Exclusivamente símbolos religiosos cristãos","Mapas de constelações modernas"]'::jsonb, 0, 'As linhas formam figuras de animais (como um macaco e um beija-flor), plantas e formas geométricas, visíveis principalmente do ar.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A cidade de Cusco, antiga capital do Império Inca, está localizada em qual país?', '["Peru","Bolívia","Equador","Colômbia"]'::jsonb, 0, 'Cusco foi a capital do Império Inca e está localizada nos Andes peruanos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Lago Titicaca, um dos lagos navegáveis mais altos do mundo, é compartilhado por quais dois países?', '["Peru e Bolívia","Peru e Equador","Bolívia e Chile","Chile e Argentina"]'::jsonb, 0, 'O Lago Titicaca fica na fronteira entre o Peru e a Bolívia, nos Andes.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Cristo de la Concordia, uma das maiores estátuas de Cristo do mundo, está localizado em qual cidade boliviana?', '["Cochabamba","La Paz","Santa Cruz","Sucre"]'::jsonb, 0, 'O Cristo de la Concordia, uma estátua monumental inspirada no Cristo Redentor, fica na cidade de Cochabamba, na Bolívia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Deserto do Atacama, um dos lugares mais áridos do mundo, está localizado em qual país?', '["Chile","Peru","Bolívia","Argentina"]'::jsonb, 0, 'O Deserto do Atacama, no norte do Chile, é considerado um dos lugares mais secos do planeta.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Ilha de Páscoa, famosa por suas estátuas monumentais chamadas moai, pertence a qual país?', '["Chile","Peru","Nova Zelândia","Estados Unidos"]'::jsonb, 0, 'A Ilha de Páscoa (Rapa Nui) é um território chileno localizado no Oceano Pacífico.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que são os ''moai'', esculturas monumentais características da Ilha de Páscoa?', '["Grandes estátuas de pedra com rostos humanos estilizados","Templos subterrâneos","Instrumentos musicais tradicionais","Tipos de canoas cerimoniais"]'::jsonb, 0, 'Os moai são estátuas monumentais de pedra, com rostos humanos estilizados, esculpidas pelos antigos habitantes polinésios da ilha.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Cidade do México foi construída sobre as ruínas de qual antiga capital asteca?', '["Tenochtitlán","Teotihuacán","Tikal","Palenque"]'::jsonb, 0, 'A atual Cidade do México foi erguida sobre as ruínas de Tenochtitlán, a antiga capital do Império Asteca.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A cidade antiga de Teotihuacán, com suas grandes pirâmides do Sol e da Lua, está localizada próxima a qual cidade moderna?', '["Cidade do México","Guadalajara","Monterrey","Cancún"]'::jsonb, 0, 'Teotihuacán fica a cerca de 40 km da Cidade do México e é um dos maiores sítios arqueológicos da Mesoamérica.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Pirâmide do Sol, em Teotihuacán, é considerada uma das maiores pirâmides do mundo em qual medida?', '["Volume","Altura absoluta","Número de degraus","Peso total"]'::jsonb, 0, 'A Pirâmide do Sol de Teotihuacán está entre as maiores estruturas piramidais do mundo em termos de volume.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Museu Guggenheim de Bilbao, marco da arquitetura contemporânea, está localizado em qual país?', '["Espanha","México","Argentina","Estados Unidos"]'::jsonb, 0, 'O Museu Guggenheim Bilbao, projetado por Frank Gehry, fica na cidade de Bilbao, no País Basco, Espanha.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A cidade de Cartagena, com seu centro histórico colonial murado, está localizada em qual país sul-americano?', '["Colômbia","Venezuela","Equador","Panamá"]'::jsonb, 0, 'Cartagena das Índias, com suas muralhas coloniais bem preservadas, fica na costa caribenha da Colômbia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Cidade Perdida (Ciudad Perdida), sítio arqueológico pré-colombiano nas montanhas, está localizada em qual país?', '["Colômbia","Peru","Equador","Venezuela"]'::jsonb, 0, 'A Ciudad Perdida, construída pelo povo Tayrona, fica na Serra Nevada de Santa Marta, na Colômbia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Cristo del Pacífico, outra grande estátua de Cristo na América do Sul, está localizado em qual cidade peruana?', '["Lima","Cusco","Arequipa","Trujillo"]'::jsonb, 0, 'O Cristo del Pacífico fica na cidade de Lima, capital do Peru, com vista para o Oceano Pacífico.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Casa Rosada, sede do governo argentino, está localizada em qual cidade?', '["Buenos Aires","Córdoba","Rosário","Mendoza"]'::jsonb, 0, 'A Casa Rosada é a sede do Poder Executivo argentino, localizada na Plaza de Mayo, em Buenos Aires.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Teatro Colón, uma das casas de ópera mais renomadas do mundo, está localizado em qual cidade?', '["Buenos Aires","Santiago","Montevidéu","Assunção"]'::jsonb, 0, 'O Teatro Colón, reconhecido internacionalmente por sua acústica, fica em Buenos Aires, na Argentina.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Glaciar Perito Moreno, uma das maiores atrações naturais da Argentina, está localizado em qual região?', '["Patagônia","Pampas","Chaco","Cuyo"]'::jsonb, 0, 'O Glaciar Perito Moreno fica na região da Patagônia argentina, dentro do Parque Nacional Los Glaciares.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Canal do Panamá, importante via de navegação que conecta dois oceanos, liga quais massas de água?', '["O Oceano Atlântico e o Oceano Pacífico","O Oceano Atlântico e o Mar do Caribe apenas","O Golfo do México e o Oceano Pacífico","O Mar do Caribe e o Golfo do México"]'::jsonb, 0, 'O Canal do Panamá conecta o Oceano Atlântico ao Oceano Pacífico, sendo uma das obras de engenharia mais importantes do mundo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Tikal, importante sítio arqueológico maia com grandes pirâmides em meio à selva, está localizado em qual país?', '["Guatemala","México","Honduras","Belize"]'::jsonb, 0, 'Tikal, um dos maiores centros urbanos da civilização maia, está localizado no norte da Guatemala.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Central Park, um dos parques urbanos mais famosos do mundo, está localizado em qual cidade?', '["Nova York","Chicago","Los Angeles","Boston"]'::jsonb, 0, 'O Central Park é um extenso parque urbano localizado no centro da ilha de Manhattan, em Nova York.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Empire State Building, um dos arranha-céus mais famosos do mundo, está localizado em qual cidade?', '["Nova York","Chicago","Filadélfia","Miami"]'::jsonb, 0, 'O Empire State Building fica no bairro de Manhattan, em Nova York, e foi por décadas o edifício mais alto do mundo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Parque Nacional Yellowstone, conhecido por seus gêiseres, está localizado principalmente em qual estado americano?', '["Wyoming","Colorado","Utah","Montana (parcialmente correto, mas o principal é Wyoming)"]'::jsonb, 0, 'Yellowstone está localizado principalmente no estado de Wyoming, embora se estenda também por Montana e Idaho.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Grand Canyon, um dos cânions mais famosos do mundo, foi formado ao longo de milhões de anos pela erosão de qual rio?', '["Rio Colorado","Rio Mississippi","Rio Grande","Rio Columbia"]'::jsonb, 0, 'O Grand Canyon foi esculpido ao longo de milhões de anos pela erosão constante do Rio Colorado.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Torre CN, um dos marcos mais reconhecíveis do Canadá, está localizada em qual cidade?', '["Toronto","Vancouver","Montreal","Ottawa"]'::jsonb, 0, 'A Torre CN, por muitos anos considerada a estrutura autônoma mais alta do mundo, fica em Toronto.');
insert into tourism_questions (question, options, correct_index, explanation) values ('As Cataratas do Niágara, compartilhadas entre dois países, ficam na fronteira entre quais nações?', '["Estados Unidos e Canadá","Estados Unidos e México","Canadá e Groenlândia (Dinamarca)","Estados Unidos apenas, sem fronteira"]'::jsonb, 0, 'As Cataratas do Niágara estão localizadas na fronteira entre os Estados Unidos e o Canadá.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Château Frontenac, um dos hotéis mais fotografados do mundo, está localizado em qual cidade canadense?', '["Cidade de Quebec","Toronto","Montreal","Ottawa"]'::jsonb, 0, 'O Château Frontenac, com sua arquitetura de castelo, é um marco histórico da Cidade de Quebec, no Canadá.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Casa da Ópera de Sydney, embora não fique nas Américas, é frequentemente comparada em fama a monumentos americanos. Em que continente ela realmente está?', '["Oceania","América do Norte","Ásia","Europa"]'::jsonb, 0, 'A Casa da Ópera de Sydney está localizada na Austrália, no continente da Oceania, e não nas Américas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Monumento Nacional Mount Vernon, antiga propriedade de George Washington, está localizado em qual estado americano?', '["Virgínia","Maryland","Pensilvânia","Nova York"]'::jsonb, 0, 'Mount Vernon, residência do primeiro presidente dos Estados Unidos, fica no estado da Virgínia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Monumento a Washington, obelisco que homenageia o primeiro presidente americano, está localizado em qual cidade?', '["Washington D.C.","Nova York","Boston","Richmond"]'::jsonb, 0, 'O Monumento a Washington é um grande obelisco localizado no National Mall, em Washington D.C.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Lincoln Memorial, dedicado ao presidente Abraham Lincoln, está localizado em qual cidade?', '["Washington D.C.","Springfield","Gettysburg","Chicago"]'::jsonb, 0, 'O Lincoln Memorial fica no National Mall, em Washington D.C., próximo ao Monumento a Washington.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Machu Picchu, Cusco e o Vale Sagrado são atrações turísticas concentradas em qual região montanhosa da América do Sul?', '["Os Andes","Os Alpes (que são europeus)","A Cordilheira Litorânea brasileira","A Serra Madre mexicana"]'::jsonb, 0, 'Machu Picchu, Cusco e o Vale Sagrado estão localizados na Cordilheira dos Andes, no Peru.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Cristo Redentor no Rio de Janeiro e o Cristo de la Concordia na Bolívia têm em comum o fato de serem, ambos, o quê?', '["Grandes estátuas monumentais de Jesus Cristo","Réplicas exatas uma da outra","Construções feitas pelo mesmo arquiteto","Monumentos de mesma altura exata"]'::jsonb, 0, 'Ambas são estátuas monumentais representando Jesus Cristo, embora sejam obras distintas em países diferentes.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Palácio Nacional, importante edifício histórico do México, está localizado em qual praça da Cidade do México?', '["Zócalo (Praça da Constituição)","Praça Garibaldi","Alameda Central","Plaza de las Tres Culturas"]'::jsonb, 0, 'O Palácio Nacional fica na praça conhecida como Zócalo, o principal centro histórico e político da Cidade do México.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Chichén Itzá e outros grandes centros maias declinaram, segundo teorias arqueológicas, principalmente por causa de quê?', '["Uma combinação de fatores como seca, guerras e mudanças políticas","Uma única grande invasão estrangeira","Um vulcão que destruiu toda a região","A chegada dos europeus no século XVI (que ocorreu muito depois)"]'::jsonb, 0, 'O declínio dos grandes centros maias clássicos é atribuído por arqueólogos a uma combinação de fatores, incluindo secas prolongadas, conflitos internos e mudanças econômicas.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Casa da Ópera de Sydney, um dos edifícios mais reconhecíveis do mundo, está localizada em qual país?', '["Austrália","Nova Zelândia","Estados Unidos","Reino Unido"]'::jsonb, 0, 'A Casa da Ópera de Sydney fica na baía de Sydney, na Austrália, e é Patrimônio Mundial da UNESCO.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Quem foi o arquiteto responsável pelo projeto icônico da Casa da Ópera de Sydney, com suas ''velas'' brancas?', '["Jørn Utzon","Frank Gehry","Renzo Piano","Norman Foster"]'::jsonb, 0, 'O projeto foi criado pelo arquiteto dinamarquês Jørn Utzon, vencedor de um concurso internacional em 1957.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Grande Barreira de Corais, embora seja uma formação natural e não um monumento construído, está localizada ao largo de qual país?', '["Austrália","Indonésia","Filipinas","Papua-Nova Guiné"]'::jsonb, 0, 'A Grande Barreira de Corais fica no Mar de Coral, ao longo da costa nordeste da Austrália.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Angkor Wat, um dos maiores complexos religiosos do mundo, está localizado em qual país?', '["Camboja","Tailândia","Vietnã","Laos"]'::jsonb, 0, 'Angkor Wat, originalmente um templo hindu depois convertido ao budismo, fica próximo à cidade de Siem Reap, no Camboja.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Angkor Wat foi originalmente construído como templo dedicado a qual religião?', '["O hinduísmo","O budismo, desde sua fundação","O islamismo","O cristianismo"]'::jsonb, 0, 'Angkor Wat foi originalmente construído no século XII como templo hindu dedicado ao deus Vishnu, sendo depois gradualmente convertido em templo budista.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Qual antigo império é responsável pela construção de Angkor Wat e da cidade de Angkor?', '["O Império Khmer","O Império Mongol","O Império Chola","O Sultanato de Malaca"]'::jsonb, 0, 'Angkor Wat foi construído pelo Império Khmer, que dominou grande parte do Sudeste Asiático entre os séculos IX e XV.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A cidade de Bagan, com milhares de templos e pagodes antigos, está localizada em qual país?', '["Mianmar","Tailândia","Camboja","Laos"]'::jsonb, 0, 'Bagan, com mais de 2.000 templos e pagodes preservados, fica em Mianmar (antiga Birmânia).');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo Shwedagon, um dos santuários budistas mais sagrados, coberto por ouro genuíno, está localizado em qual cidade?', '["Yangon, em Mianmar","Bangkok, na Tailândia","Hanói, no Vietnã","Vientiane, no Laos"]'::jsonb, 0, 'A Pagode Shwedagon, com sua grande estupa coberta de ouro, fica na cidade de Yangon, em Mianmar.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Grande Palácio Real, importante complexo histórico tailandês, está localizado em qual cidade?', '["Bangkok","Chiang Mai","Phuket","Pattaya"]'::jsonb, 0, 'O Grande Palácio Real, antiga residência oficial dos reis da Tailândia, fica no centro de Bangkok.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo de Buda de Esmeralda, um dos mais sagrados da Tailândia, está localizado dentro de qual complexo?', '["O Grande Palácio de Bangkok","O Palácio de Ayutthaya","A cidade de Chiang Mai","O templo de Wat Arun isoladamente"]'::jsonb, 0, 'O Templo de Buda de Esmeralda (Wat Phra Kaew) fica dentro do complexo do Grande Palácio, em Bangkok.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A cidade histórica de Hoi An, com sua arquitetura colonial preservada, está localizada em qual país?', '["Vietnã","Camboja","Tailândia","Laos"]'::jsonb, 0, 'Hoi An, antigo porto comercial, é uma cidade histórica bem preservada no centro do Vietnã.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Baía de Halong, famosa por suas formações rochosas emergindo do mar, está localizada em qual país?', '["Vietnã","Filipinas","Indonésia","Malásia"]'::jsonb, 0, 'A Baía de Halong, com milhares de ilhotes de calcário, fica no norte do Vietnã.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo Borobudur, o maior templo budista do mundo, está localizado em qual país?', '["Indonésia","Malásia","Filipinas","Cingapura"]'::jsonb, 0, 'O Borobudur, considerado o maior monumento budista do mundo, fica na ilha de Java, na Indonésia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo Borobudur é estruturado em camadas, representando simbolicamente qual conceito budista?', '["A jornada em direção à iluminação","Os quatro elementos da natureza","A hierarquia militar do império","As estações do ano"]'::jsonb, 0, 'A estrutura em níveis do Borobudur representa simbolicamente a jornada budista da vida terrena até a iluminação espiritual.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Templo Prambanan, um dos maiores complexos hindus do Sudeste Asiático, está localizado próximo a qual cidade indonésia?', '["Yogyakarta","Jacarta","Bali (Denpasar)","Surabaya"]'::jsonb, 0, 'O Templo Prambanan, dedicado à Trimurti hindu (Brahma, Vishnu e Shiva), fica próximo à cidade de Yogyakarta, em Java.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A ilha de Bali, famosa por seus templos hindus e paisagens, pertence a qual país?', '["Indonésia","Malásia","Filipinas","Tailândia"]'::jsonb, 0, 'Bali é uma ilha indonésia conhecida por sua cultura hindu única em meio a um país majoritariamente muçulmano.');
insert into tourism_questions (question, options, correct_index, explanation) values ('As Torres Petronas, um dos arranha-céus gêmeos mais famosos do mundo, estão localizadas em qual cidade?', '["Kuala Lumpur","Cingapura","Jacarta","Manila"]'::jsonb, 0, 'As Torres Petronas, antigo edifício mais alto do mundo, ficam em Kuala Lumpur, capital da Malásia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Marina Bay Sands, complexo com piscina no topo em formato de barco, está localizado em qual cidade-estado?', '["Cingapura","Hong Kong","Kuala Lumpur","Bangkok"]'::jsonb, 0, 'O Marina Bay Sands, com sua estrutura icônica em forma de barco no topo de três torres, fica em Cingapura.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O que caracteriza a estrutura Gardens by the Bay, importante atração de Cingapura, com suas árvores artificiais gigantes?', '["''Supertrees'' (superárvores) que combinam vegetação real com estrutura artificial","Réplicas de templos antigos","Um zoológico exclusivamente aquático","Uma pirâmide de vidro"]'::jsonb, 0, 'O parque é famoso por suas ''supertrees'', estruturas verticais gigantes cobertas de plantas reais, combinando natureza e tecnologia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Grande Muralha da China à parte, qual outra grande fortificação histórica protege a antiga capital coreana de Seul?', '["A Fortaleza de Hwaseong","A Muralha de Pyongyang","O Forte de Busan","A Cidadela de Jeju"]'::jsonb, 0, 'A Fortaleza de Hwaseong, na cidade de Suwon, próxima a Seul, é um importante exemplo de fortificação coreana do século XVIII.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Palácio Gyeongbokgung, principal palácio real da Coreia, está localizado em qual cidade?', '["Seul","Busan","Incheon","Daegu"]'::jsonb, 0, 'O Gyeongbokgung foi o principal palácio real da dinastia Joseon, localizado no centro de Seul, na Coreia do Sul.');
insert into tourism_questions (question, options, correct_index, explanation) values ('As Grutas de Seokguram, importante sítio budista coreano com uma estátua de Buda esculpida em granito, ficam próximas a qual cidade?', '["Gyeongju","Seul","Busan","Jeju"]'::jsonb, 0, 'A Gruta de Seokguram fica nas montanhas próximas à antiga capital de Gyeongju, na Coreia do Sul.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Grande Mesquita de Sultão Ahmed, conhecida como ''Mesquita Azul'', está localizada em qual cidade?', '["Istambul","Ancara","Meca","Cairo"]'::jsonb, 0, 'A Mesquita Azul, famosa por seus azulejos internos, fica em Istambul, na Turquia.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Por que a Mesquita de Sultão Ahmed é popularmente chamada de ''Mesquita Azul''?', '["Pelos azulejos azuis que decoram seu interior","Por sua cúpula externa ser pintada de azul","Por ficar à beira de um mar de águas azuis","Por ter sido construída com pedra azulada"]'::jsonb, 0, 'O apelido vem dos milhares de azulejos de tons azuis usados na decoração interna da mesquita.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A cidade de Meca, destino de peregrinação obrigatória para muçulmanos, está localizada em qual país?', '["Arábia Saudita","Egito","Jordânia","Iraque"]'::jsonb, 0, 'Meca, cidade sagrada do islamismo e local de nascimento do profeta Maomé, fica na Arábia Saudita.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Caaba, estrutura em formato de cubo considerada o local mais sagrado do islamismo, está localizada dentro de qual mesquita?', '["A Grande Mesquita de Meca (Masjid al-Haram)","A Mesquita Azul, em Istambul","A Mesquita de Al-Aqsa, em Jerusalém","A Grande Mesquita de Damasco"]'::jsonb, 0, 'A Caaba fica no centro da Grande Mesquita de Meca e é o ponto para o qual os muçulmanos se voltam durante as orações.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Cúpula da Rocha, importante santuário islâmico com cúpula dourada, está localizada em qual cidade?', '["Jerusalém","Meca","Medina","Damasco"]'::jsonb, 0, 'A Cúpula da Rocha é um santuário islâmico localizado no Monte do Templo, em Jerusalém.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Muro das Lamentações, importante local sagrado para o judaísmo, também está localizado em qual cidade?', '["Jerusalém","Tel Aviv","Belém","Haifa"]'::jsonb, 0, 'O Muro das Lamentações, remanescente do antigo Segundo Templo, fica na Cidade Velha de Jerusalém.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A cidade de Petra, esculpida na rocha, apesar de estar na Ásia (Jordânia), também é associada culturalmente a qual povo comerciante do deserto?', '["Os nabateus","Os fenícios","Os assírios","Os hititas"]'::jsonb, 0, 'Petra foi construída pelos nabateus, um povo árabe que controlava importantes rotas comerciais no deserto.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Grande Mesquita de Xeique Zayed, uma das maiores mesquitas do mundo, está localizada em qual cidade?', '["Abu Dhabi","Dubai","Doha","Manama"]'::jsonb, 0, 'A Grande Mesquita Xeique Zayed fica em Abu Dhabi, capital dos Emirados Árabes Unidos.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Burj Khalifa, o edifício mais alto do mundo atualmente, está localizado em qual cidade?', '["Dubai","Abu Dhabi","Doha","Riade"]'::jsonb, 0, 'O Burj Khalifa, inaugurado em 2010, fica em Dubai, nos Emirados Árabes Unidos, e é o edifício mais alto do mundo.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Persépolis, antiga capital cerimonial do Império Persa, está localizada em qual país atual?', '["Irã","Iraque","Turquia","Afeganistão"]'::jsonb, 0, 'As ruínas de Persépolis, antiga capital do Império Aquemênida, estão localizadas no atual Irã.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Persépolis foi fundada, segundo registros históricos, por qual rei persa?', '["Dario I","Ciro, o Grande","Xerxes I, isoladamente","Alexandre, o Grande"]'::jsonb, 0, 'A construção de Persépolis foi iniciada por Dario I, por volta de 518 a.C., sendo expandida por seus sucessores.');
insert into tourism_questions (question, options, correct_index, explanation) values ('As Torres do Silêncio, estruturas usadas em rituais funerários zoroastristas, são encontradas principalmente em qual país, associado a essa antiga religião persa?', '["Irã","Iraque","Síria","Líbano"]'::jsonb, 0, 'As Torres do Silêncio são estruturas associadas à antiga religião zoroastrista, historicamente praticada na região do atual Irã.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Grande Mesquita de Damasco, uma das mais antigas e importantes do mundo islâmico, está localizada em qual país?', '["Síria","Líbano","Jordânia","Iraque"]'::jsonb, 0, 'A Grande Mesquita de Damasco, construída no início do século VIII, fica na capital da Síria.');
insert into tourism_questions (question, options, correct_index, explanation) values ('Babilônia, antiga cidade mesopotâmica associada aos lendários Jardins Suspensos, ficava localizada no que hoje é qual país?', '["Iraque","Irã","Síria","Jordânia"]'::jsonb, 0, 'As ruínas da antiga Babilônia estão localizadas no atual Iraque, próximas à cidade de Bagdá.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Grande Mesquita de Samarra, no Iraque, é famosa por seu minarete em formato espiral, chamado de:', '["Malwiya","Kaaba","Al-Aqsa","Sultanahmet"]'::jsonb, 0, 'O minarete Malwiya, com sua rampa espiral externa, é a marca mais reconhecível da Grande Mesquita de Samarra.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Uluru (Ayers Rock), uma das formações rochosas mais sagradas para os povos aborígenes, está localizado em qual país?', '["Austrália","Nova Zelândia","África do Sul","Estados Unidos"]'::jsonb, 0, 'O Uluru é uma imensa formação rochosa localizada no centro da Austrália, sagrada para os povos aborígenes locais.');
insert into tourism_questions (question, options, correct_index, explanation) values ('O Uluru é especialmente famoso por qual fenômeno visual que ocorre ao entardecer?', '["A mudança de cor da rocha, que parece ficar avermelhada/laranja","O surgimento de um arco-íris permanente","A formação de neblina colorida","O brilho fosforescente da própria pedra"]'::jsonb, 0, 'O Uluru é conhecido por mudar de tonalidade ao longo do dia, ficando especialmente avermelhado ao pôr do sol.');
insert into tourism_questions (question, options, correct_index, explanation) values ('A Casa da Ópera de Sydney foi reconhecida pela UNESCO como Patrimônio Mundial em qual século?', '["Século XXI (2007)","Século XX (1980)","Século XIX","Ainda não foi reconhecida"]'::jsonb, 0, 'A Casa da Ópera de Sydney foi declarada Patrimônio Mundial pela UNESCO em 2007, sendo uma das construções mais recentes com esse título.');
